(function(g){g.OPERATIONS_CONTENT=[{"id":"pr1","caseId":"pr1-dynacard","stageId":"production","short":"示功图诊断","title":"同样不饱满的示功图，为什么需要分开判断？","question":"从载荷—位移形状识别异常候选，能否减少逐张翻图，又保留疑难卡片？","methods":["cv"],"intro":"抽油机带动杆柱和井下泵往复运动，一次冲程会形成载荷—位移闭合曲线。本例先看仪器测到了什么，再把人工形状参照与CNN放在同一张卡片上检查，保留需要进一步复核的结果。","problem":"现场常按曲线饱满程度、拐角和上下冲程的差异判读。供液、气体、杆柱振动和阀门状态都能改变图形；不同原因可能出现近似形状，逐张判图也会产生不一致。","why":"CNN把相邻像素组成局部形状，再组合成整张图的类别线索。它接手的是重复的图形筛查；形状基线提供可解释参照，检泵记录和生产背景仍负责验证具体故障。","input":"同一张示功图的位移—载荷点集及其栅格图；井分组、卡片来源和图形标签随记录保留。","output":"四类形状候选、各类得分和低分复核标记；12张形状示范与全部55张留出图的门槛统计分开展示。","data":"开放参考库含245张现场档案数字化形状图、3张有物理单位的实测地面卡和98张合成卡。主实验仅用档案图，按匿名井划分为150张训练、40张检查、55张留出。页面按原始四类形状标签各取源ID排序前3张，共12张，不按模型得分或正确性选图；覆盖率和接受结果标签一致率使用全部55张。源ID前缀不表示形状类别，实测地面卡与合成卡不混入这组验证。","limits":["四类标签描述图形现象，未附逐张检泵证实的故障原因。模型得分不等于经过校准的故障概率。","档案图坐标经过归一化，没有载荷与冲程的物理单位；地面卡还受杆柱动力学影响，不能直接当井下泵卡。","代码库明确使用MIT许可；原始私人档案的独立数据授权声明未找到。发布时保留来源与许可说明，跨油田适用性需另验。"],"experiment":"固定一张留出井卡片，提高接受门槛，观察它是否转为“待复核”；再切换其他形状。汇总变化始终在完整55张留出图上计算：已接受结果的标签一致率提高时，覆盖率是否同时下降？不要把当前一张卡的对错当成总体指标。","professional":[{"title":"一圈曲线记录了什么","text":"示功图横轴是位移，纵轴是载荷，上下冲程组成一个闭合周期。带物理单位时，曲线包围面积与一周期机械功相关；归一化后的形状图只保留相对轮廓，不能据此计算实际功率。"},{"title":"地面看到的形状经过了杆柱传递","text":"地面光杆载荷同时包含液柱负荷、杆柱自重和动态响应。井下泵充满程度与阀门动作会影响曲线，但地面卡到井下泵卡需要动力学转换，不能只把两种图缩放到同一画布就视为等价。"},{"title":"图形标签怎样连接到工程判断","text":"本例的蝴蝶形、充满不足、充满塌陷和饱满卡来自档案形状标注。它们适合学习图形识别；要判断气锁、漏失或杆柱问题，还需冲次、液量、历史变化与作业验证。"}],"steps":[{"name":"定义图形筛查任务","do":"明确四类形状字典，约定低分卡片进入人工复核。把图形判断与具体故障原因分开。","output":"类别字典、可接受结果与待复核结果的定义。","blockId":"01"},{"name":"配对曲线与来源","do":"读取点集，核对地面/井下图形、归一化/物理单位和来源；按匿名井分组，再将同一轮廓转换为统一尺寸图像。","output":"带井分组的栅格图、参考标签与原始点集。","blockId":"02"},{"name":"传统：比较轮廓特征","do":"在同一输入上比较饱满程度、上下轮廓差异等形状量，用固定形状基线给出候选。","output":"能回到轮廓解释的基线类别。","blockId":"03traditional"},{"name":"智能：CNN读取图形","do":"只用训练井拟合CNN，读取整张栅格图；对留出井输出四类得分，并按接受门槛标出疑难图。","output":"CNN类别、得分与复核标记。","blockId":"03intelligent"},{"name":"对照同一张卡","do":"联动查看原点集、原始形状标签、基线与CNN；在全部55张留出图上重算门槛覆盖率及已接受结果的标签一致率，再回看12张示范中的高分错例。","output":"完整55张的门槛统计、固定混淆矩阵与可回到原卡片的跨井错例。","blockId":"04"},{"name":"保存复核清单","do":"导出卡片ID、井分组、来源、形状候选和门槛。需要故障结论时再连接现场生产与检泵证据。","output":"可追溯的示功图候选表。","blockId":"05"}],"glossary10":[["示功图","Dynamometer card","一次冲程的载荷—位移关系，本例主要识别相对轮廓。"],["光杆","Polished rod","地面与杆柱连接处，实测地面载荷的常见位置。"],["地面卡","Surface card","地面测得的曲线，含杆柱动态影响。"],["井下泵卡","Downhole pump card","描述井下泵载荷与位移的曲线，通常需转换或井下测量。"],["充满程度","Pump fillage","泵筒被液体充满的程度，须结合工况解释。"],["栅格化","Rasterization","把曲线点集转换为统一的像素输入。"],["卷积网络","Convolutional neural network","用共享卷积核组合局部形状，输出类别得分。"],["形状基线","Shape baseline","用少量轮廓量建立的可解释比较方法。"],["按井留出","Well holdout","同一匿名井的卡片只进入一种资料分区。"],["覆盖率","Coverage","达到接受门槛的卡片占全部待判卡片的比例。"]],"primarySource":{"title":"digitalmodel · 示功图参考卡片库","url":"https://github.com/vamseeachanta/digitalmodel/issues/1288","license":"代码库MIT；原档案独立授权未核实，逐卡保留实测/数字化/合成来源。"},"research":{"title":"Automatic recognition of sucker-rod pumping system working conditions using dynamometer cards with transfer learning and SVM","url":"https://doi.org/10.3390/s20195659","summary":"研究把示功图转换为视觉表示，以迁移学习提取特征，再用SVM区分工况，说明轮廓可以作为自动筛查输入。","boundary":"文献采用其油田资料和标注方案；本课CNN、四类档案形状与按井留出实验另行建立，不沿用论文成绩。"},"columnMap":{"file":"dynacard-example_cards.json","recordPath":"cards[]","input":{"position":"位移点数组；档案为无量纲归一化值，实测/合成为in","load":"载荷点数组；档案为无量纲归一化值，实测/合成为lb"},"target":{"phenomenon":"仅用于监督与检查；主实验使用四类档案形状"},"meta":{"id":"源卡片ID；以-wNN-匿名井标记保守分组；butterfly前缀不代表类别","source":"field-archive-digitized / field-measured / synthetic-verified","units":"normalized / oilfield","meta.card_type":"pump / surface；不作为故障输入"},"excludeFromFeatures":["phenomenon","source","id","meta"],"derived":"统一坐标后生成灰度/占据栅格；参考标签不得绘入输入。"},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"二维卷积分类＋形状参照","color":"#b95739","artImage":"assets/images/operations/production-process-v2.webp","artBox":[4,430,294,340]},{"id":"pr2","caseId":"pr2-oil-forecast","stageId":"production","short":"产量预测","title":"产量曲线拐弯时，下一月还能沿着原趋势走吗？","question":"同一段历史，GRU能否比“上月照搬”与递减参照更好地跟踪下一月产油量？","methods":["ts"],"intro":"短期产量预测用于安排生产与发现计划偏差。本例用Volve油田的真实月度可销售产油量，保留月度体积单位，再把只使用过去数据的GRU与简单参照放在同一测试月份比较。","problem":"递减参照适合描述特定生产阶段，上月照搬则只延续最近水平。投产爬坡、停产和措施会造成突变；缺少事件记录时，模型无法提前知道这些变化。","why":"GRU通过内部状态组合多个月份的变化，学习下一月与近期历史之间的关联。是否有用取决于时间留出检验；数据量小和工况突变都可能使简单参照更稳定。","input":"预测月以前12个月的可销售产油量Sm³/月；日期与原始百万Sm³月总量用于追溯。","output":"下一月产油量预测、实际值、逐月误差，以及相同目标月份的末值与指数递减参照。","data":"Sodir官方月度数据筛选VOLVE，含2008年2月至2017年7月的114个月，其中正产油持续到2016年9月。原始油量为百万Sm³/月，本课乘10⁶后保留Sm³/月，不换成日率。训练目标至2013年12月、检查目标为2014年、测试目标为2015年1月至2016年9月；后续停产零值单独保留。","limits":["输入是油田月总量，不能代表单井日度工况，也没有足够资料进行措施效果的因果归因。","本课目标是Sm³/月，月份天数和停产时长都会影响月总量；不能把它标为日历日或开井日油率。标准状态体积也不同于地层体积。","月度样本很少。GRU能拟合训练趋势并不说明能预测突发停产，最终指标只对所列测试月份有效；本次留出结果也未保证优于末值参照。"],"experiment":"切换不同预测月份，比较GRU、上月值和递减趋势怎样偏离随后公布的实测值。固定同一月份后，再缩短可见历史月数，观察模型预测是否稳定；缩短窗口是敏感性试验，不复用原12月窗口的检验成绩。","professional":[{"title":"月产油量与油率是不同目标","text":"月产油量是一个月的累计体积，油率是单位时间的产量。不同月份的天数和停产时长都可能影响月总量。本例明确保留月度目标并统一到Sm³/月；若改成日率，需要重新定义换算和评价。"},{"title":"递减参照只能描述给定阶段","text":"工程递减分析用于描述特定生产阶段的衰减趋势。本课简单参照在过去12个月的对数月量上拟合非正斜率，形成指数外推。它没有校正开井时长或识别递减阶段，不能等同完整现场Arps分析。"},{"title":"预测必须站在当时的信息位置","text":"在预测某月时，该月及之后的实际产量尚不可用。历史窗口、标准化和参数选择都应止于允许使用的时间；滚动评价用同一预测跨度比较方法，避免随机拆分月份造成未来信息泄漏。"}],"steps":[{"name":"约定预测跨度","do":"把目标限定为下一月的油田月度可销售产油量Sm³/月，明确发出预测时能看到的最后一个月。","output":"统一的月度体积目标与一月预测跨度。","blockId":"01"},{"name":"整理月量与时间","do":"筛选VOLVE，核对年月与月总量，乘10⁶换算为Sm³/月；按时间划分资料并只用训练段计算缩放参数。","output":"带日期、来源月量与分区的月度产油序列。","blockId":"02"},{"name":"传统：末值与递减","do":"以上月产油量作为下一月预测；再用相同的过去12个月拟合非正斜率的指数参照，检查生产阶段变化。","output":"同一目标月份的两种简单预测。","blockId":"03traditional"},{"name":"智能：GRU读取历史","do":"让小型GRU依次读取允许使用的历史窗口；用检查段选定训练设置，再对留出月份作因果预测。","output":"逐月下一步预测，不读取未来实际值。","blockId":"03intelligent"},{"name":"对照误差与转折","do":"在同一月份对照三种预测与实际月产油量；除汇总MAE/RMSE外，特别查看突降、低产和停产附近的误差。","output":"逐月误差图与相同区间的指标。","blockId":"04"},{"name":"记录预测条件","do":"导出日期、原月量、Sm³/月目标、预测值及训练截止月。将缺少事件信息造成的偏差保留在记录中。","output":"可回到源月量核查的预测表。","blockId":"05"}],"glossary10":[["产油量","Oil production volume","本例为标准状态下每月可销售产油体积。"],["油率","Oil rate","单位时间产油量；本课保留月总量，不将其误标成单井日率。"],["标准立方米","Standard cubic metre / Sm³","规定标准状态下的体积单位。"],["月度体积","Monthly volume","一个自然月累计可销售产油体积，本例单位Sm³/月。"],["递减曲线","Decline curve","对给定生产阶段的衰减趋势进行参数描述。"],["末值预测","Persistence forecast","以下一个月等于最近一个月作为参照。"],["门控循环单元","Gated recurrent unit / GRU","通过门控状态组合历史信息的时序网络。"],["历史窗口","Lookback window","发出预测前允许使用的一段记录。"],["滚动起点","Rolling origin","随月份推进预测起点，始终只使用当时的过去。"],["平均绝对误差","Mean absolute error / MAE","预测与实际月产量差值绝对值的平均，单位仍是Sm³/月。"]],"primarySource":{"title":"Sodir FactPages · Monthly saleable field production","url":"https://factpages.sodir.no/en/field/TableView/Production/Saleable/Monthly","license":"Norwegian Licence for Open Government Data（NLOD）2.0。"},"research":{"title":"Equinor · Volve field data set","url":"https://www.equinor.com/energy/volve-data-sharing","summary":"Volve公开计划提供真实油田的生产与地下资料，使学生可以在完整开发背景中研究产量变化。","boundary":"本课实际数值取自Sodir官方月度油田总量，并非直接读取Volve逐井日度Excel；未复现现场措施归因或完整开发模拟。"},"columnMap":{"file":"sodir-volve-production-monthly.csv","input":{"prfYear":"记录年份","prfMonth":"记录月份","prfPrdOilNetMillSm3":"月产油量，百万Sm³；只允许历史月份进入模型"},"target":{"prfPrdOilNetMillSm3[t+1]":"下一月月产油量，乘1000000得到Sm³/月"},"meta":{"prfInformationCarrier":"必须等于VOLVE","prfNpdidInformationCarrier":"油田ID 3420717"},"derived":{"month":"YYYY-MM-01","oilSm3Month":"prfPrdOilNetMillSm3 × 1000000；不除天数"},"excludeFromFeatures":["预测月及其后的实际油量","未来作业记录","全序列统计量"]},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"因果历史窗口GRU预测","color":"#497d99","artImage":"assets/images/operations/production-process-v2.webp","artBox":[306,430,272,340]},{"id":"pr3","caseId":"pr3-injection-allocation","stageId":"production","short":"注水调配","title":"总水量不变，水应该更多分给哪口注水井？","question":"在总水量和单井上限下，响应模型如何改变配注方案，又怎样检查方案确实可行？","methods":["opt"],"intro":"注水通过补充能量和驱替流体影响周围生产井，见效常有时间滞后。本例先用开放合成注采记录建立响应代理，再实际求解受约束的配注方案；计算目标明确限定为模型预测的总液响应。","problem":"均分注水容易执行，却没有利用不同井之间的响应差异。只按最近增液追着调整，又可能忽略滞后和总水量限制；一个预测值更高的方案也可能超出单井能力。","why":"非负滞后响应模型将过去配注变化与后续产液联系起来，求解器再把目标函数与总水量、单井上限同时计算。它使“响应怎样估计”和“方案是否可行”成为两个可分别核查的问题。","input":"5口注水井、4口生产井的对齐合成历史；总配注预算、单井上下限，以及明确给定的代理模型。","output":"各注水井建议量、与均分方案相比的预测总液响应、约束剩余量和可行性状态。","data":"pywaterflood作者教程明确给出一套合成水驱资料，共298个对齐时间点，含5列注水、4列产液和一列时间。模型按前后时间段拟合与检查。原始物理流量单位未在已核对文档中确定，页面使用原始流量单位或有说明的归一化量；不擅自标成m³/d。","limits":["源数据为合成注采响应，配注效果只在本课代理模型内比较。生产列是总液响应，不能称为实测增油量。","非负关联不等于已证实的地下流线或因果连通。超出训练配注范围会增加外推风险。","单井上限和总水量是教学情景约束；资料没有实测破裂压力、分层吸水剖面或水质约束，不能直接形成现场注水指令。"],"experiment":"先减小注水总量预算，再收紧I3注水井的能力上限：分配转移到哪里？同时核对已用总量、单井上限和模型总液响应；未观测方案的响应差不能写成实测增油。","professional":[{"title":"注水见效存在时间响应","text":"一次配注调整不一定在下一条生产记录中完全体现。储层压缩性、连通和流体运动会形成延迟与衰减；注采模型需要同时考虑配注量和过去一段时间的影响。"},{"title":"CRM把复杂储层压缩成响应关系","text":"电容—电阻模型以物质平衡为出发点，用增益描述注水变化传到生产端的比例，用时间常数描述响应速度。本课采用非负滞后代理表达这一思想，拟合优劣须由留出历史检查。"},{"title":"配注优化需要目标与约束分开写","text":"目标决定怎样评价候选方案，约束决定什么方案允许执行。总水量、单井上限和调整幅度都可能限制最优分配。本例没有油水分相收益资料，因此只优化说明清楚的总液代理目标。"}],"steps":[{"name":"定义配注目标","do":"明确这次优化比较预测总液响应，固定规划时点与总水量预算；不把总液增加解释为增油。","output":"可计算的目标及允许调整的5个配注量。","blockId":"01"},{"name":"对齐注采历史","do":"按同一时间行配对注水与产液，分开训练和留出段；整理非负输入、滞后项与情景约束。","output":"注采设计矩阵、资料分区和上下限表。","blockId":"02"},{"name":"传统：均分或沿用","do":"在同一总量下计算均分方案，并显示沿用当前比例的方案；两种参照都先通过单井界限检查。","output":"符合相同约束的比较起点。","blockId":"03traditional"},{"name":"智能：拟合后求解","do":"以非负系数拟合滞后响应，再用实际约束优化算法搜索配注；每个候选都计算总量与单井可行性。","output":"模型内优化方案、目标值及求解状态。","blockId":"03intelligent"},{"name":"逐项核对方案","do":"比较每口井分配、总水量使用、上限剩余与模型预测；在留出历史查看代理误差，识别超训练范围的建议。","output":"目标改善与约束核查并列的对照。","blockId":"04"},{"name":"导出情景方案","do":"保存当前预算、界限、注水向量、预测量和模型版本；后续工程复核需要增加真实压力、分层与油水资料。","output":"带假设和可行性说明的配注情景表。","blockId":"05"}],"glossary10":[["配注量","Injection allocation","分给各注水井或层段的注入量。"],["注采响应","Injection–production response","注水变化与生产端后续变化的关系。"],["连通增益","Connectivity gain","代理模型中衡量注水影响强弱的非负系数。"],["时间常数","Time constant","描述响应延迟和衰减快慢的模型量。"],["电容—电阻模型","Capacitance–resistance model / CRM","用简化物质平衡近似井间动态响应。"],["滞后项","Lag term","把较早注水量作为当前产液的输入。"],["总液量","Total liquid production","包含油和水的液体响应，本例不拆成油量。"],["目标函数","Objective function","用一个明确数值评价候选配注方案。"],["可行域","Feasible region","同时满足总量与单井界限的方案集合。"],["约束剩余量","Constraint slack","距离限制边界还剩多少；负值表示违反约束。"]],"primarySource":{"title":"pywaterflood · 7 Minutes to Pywaterflood","url":"https://pywaterflood.readthedocs.io/en/v0.3.1/user-guide/7-minutes-to-pywaterflood.html","license":"BSD-2-Clause代码库；教程明确标为synthetic waterflood。"},"research":{"title":"Pywaterflood: Well connectivity analysis through capacitance-resistance modeling","url":"https://doi.org/10.21105/joss.06191","summary":"作者公开CRM实现，用注采历史估计响应增益和时间尺度，并给出小规模合成水驱教程，便于复核历史拟合与预测。","boundary":"本课用非负滞后代理和受约束配注作为教学实现，不宣称复现完整储层模拟，也不把预测总液变化称为现场增油效果。"},"columnMap":{"files":["pywaterflood-time.csv","pywaterflood-injection.csv","pywaterflood-production.csv"],"header":"三个CSV均无表头，按同一行号严格对齐。","input":{"time.csv[:,0]":"原始时间坐标；保留原单位，不自行补为天","injection.csv[:,0:5]":"5口注水井历史，原始流量单位"},"target":{"production.csv[:,0:4]":"4口生产井总液响应，原始流量单位"},"meta":{"row_index":"对齐与时间划分索引"},"scenario":{"budget":"同一原始/归一化流量尺度下的总水量上限","lower[5]":"单井下限，情景设定","upper[5]":"单井上限，情景设定"},"excludeFromFeatures":["留出时间段产液作为已知输入","最优方案标签（源数据未提供）"],"derived":"由训练段构建非负滞后矩阵；若归一化，保存同一个训练参考尺度。"},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"非负滞后CRM＋有界配注优化","color":"#8b65a0","artImage":"assets/images/operations/production-process-v2.webp","artBox":[589,430,271,340]},{"id":"pr4","caseId":"pr4-esp-warning","stageId":"production","short":"电潜泵预警","title":"电流升高，是调频响应还是持续异常？","question":"先预测正常运行响应，再检查残差，能否减少正常工况变化引起的报警？","methods":["ts"],"intro":"电潜泵的电流、温度和压力会随工况共同变化。为保留真实的时间预测任务，本例明确使用可复现的运行片段仿真，先预测下一时刻，再用残差监测持续偏离；真实ESPset振动资料只作设备与故障标签背景。","problem":"只设一个电流上限，可能把正常调频后的负荷变化当成故障，也可能漏掉尚未越界的缓慢异常。需要区分“运行条件变了”与“同样运行条件下响应不再正常”。","why":"正常历史建立了条件响应参照，预测器先回答当前工况下下一步应怎样变化。残差监测再寻找持续偏离；改变门槛会在误报和检出延迟之间产生可观察的取舍。","input":"仿真片段中的时间、电流A、温度°C、压力MPa和频率Hz；每次预测只读取已发生的记录。","output":"下一时刻预测、逐通道残差、汇总异常分数、报警时刻与相对仿真异常起点的检出延迟。","data":"主实验由固定种子生成正常调频、负荷变化及持续偏移的独立运行片段，并保存异常注入起点与生成参数。按完整片段划分训练和检查，预测器只拟合正常片段。ESPset另含6032条实物泵振动谱特征、11个ESP编号及正常/不平衡等标签，但没有时间列，绝不按行号伪造运行寿命。","limits":["全部时序报警成绩都来自显式仿真；异常起点由生成器给定，不能称为真实油井提前预警时间。","ESPset的实物谱特征用于说明设备振动与故障类别，没有用它校准本例电流、压力或温度的仿真数值。","异常分数提示偏离正常参照，并不自动定位气锁、结垢或电机短路。传感器漂移也可能触发报警，检泵建议还需现场证据。"],"experiment":"在同一仿真运行片段中，提高残差报警门槛或要求更长的持续偏离：正常调频后的误报是否减少，持续异常又晚了多久才被检出？同时查看预测与原始曲线，辨认哪一个通道先偏离。","professional":[{"title":"电潜泵有相互关联的运行量","text":"电机带动多级离心泵举升井液。频率影响转速，流量和压差改变负荷，电流与温度反映电机运行响应。一个参数变化需要放在其他参数和控制动作中理解。"},{"title":"预测残差把工况与偏离分开","text":"下一步预测是根据过去历史估计正常响应，残差是实际值减去该估计。对各通道按训练段正常波动尺度标准化后，可以比较电流与温度等不同单位的偏离，避免大数值通道独自支配分数。"},{"title":"报警必须有明确的时间参照","text":"本例异常起点是仿真注入变化开始的时刻，报警时刻来自因果计算。两者之差是仿真检出延迟；没有真实故障发生与检修记录，就不能把这段差值转写成现场可提前多少天检泵。"}],"steps":[{"name":"定义监测问题","do":"把任务定为正常运行预测后的异常提示，明确正常工况变化与仿真持续偏移的区别。","output":"监测通道、报警规则与仿真起点定义。","blockId":"01"},{"name":"按运行片段分组","do":"保留种子、工况脚本和时间间隔；正常训练片段、调参片段与留出片段分开，标签只供评价。","output":"有生成记录的多通道片段。","blockId":"02"},{"name":"传统：单电流门槛","do":"以同一电流曲线和固定上限筛查，观察调频引起的正常上升是否也越界。","output":"易解释的电流阈值报警带。","blockId":"03traditional"},{"name":"智能：预测后看残差","do":"正常片段训练时序预测器，用过去窗口预测下一点；汇总标准化残差，再按门槛与持续条件触发。","output":"预测、残差分数和因果报警带。","blockId":"03intelligent"},{"name":"核对误报与延迟","do":"把两种报警与频率变化、异常注入起点放在同一时间轴；计算正常段报警和仿真检出延迟。","output":"明确区分正常变化与持续偏离的对照。","blockId":"04"},{"name":"保存报警证据","do":"导出片段、种子、原值、预测、残差、门槛和报警时刻；保留“仿真”标记及不能定位故障的说明。","output":"可重现的仿真监测记录。","blockId":"05"}],"glossary10":[["电潜泵","Electrical submersible pump / ESP","由井下电机驱动多级离心泵的人工举升设备。"],["调频","Variable-frequency operation","通过频率改变运行转速，属于可能的正常工况变化。"],["运行片段","Operating episode","一段完整连续记录，划分资料时整体分组。"],["一步预测","One-step-ahead forecast","只用过去记录估计下一个时间点。"],["预测残差","Forecast residual","当前观测减去此前发出的预测。"],["标准化残差","Standardized residual","按正常训练波动尺度换算后的偏离。"],["异常分数","Anomaly score","衡量偏离正常参照的数值，不是故障概率。"],["持续触发","Persistence trigger","偏离连续满足条件后才报警。"],["检出延迟","Detection delay","本例为仿真起点到首次报警的时间差。"],["振动谱","Vibration spectrum","振动幅值随频率的分布；ESPset没有运行时间顺序。"]],"primarySource":{"title":"ESPset v3 · 真实ESP振动测试（仅作背景）","url":"https://data.mendeley.com/datasets/m268jsw339/3","license":"ESPset数据CC BY 4.0；主实验运行时序为独立教学仿真。"},"research":{"title":"An open source experimental framework and public dataset for vibration-based fault diagnosis of electrical submersible pumps used on offshore oil exploration","url":"https://doi.org/10.1016/j.knosys.2024.111452","summary":"研究公开安装前实物ESP振动测试及比较框架，覆盖正常、不平衡、不对中、摩擦和传感器故障等类别，强调设备分组对验证的重要性。","boundary":"谱特征分类与连续SCADA提前预警是不同问题。本课没有把ESPset样本顺序当时间，也没有把论文分类结果当作仿真预警成绩。"},"columnMap":{"simulationSchema":{"episode_id":"完整运行片段ID；按此分组","t":"从片段起点开始的时间，必须另存dt与单位","current_A":"模拟电流A","temperature_C":"模拟温度°C","pressure_MPa":"模拟压力MPa","frequency_Hz":"模拟运行频率Hz","anomaly_onset_t":"生成器给定起点，仅用于评价","seed":"生成种子，仅用于追溯"},"input":["过去窗口的current_A","过去窗口的temperature_C","过去窗口的pressure_MPa","已知历史frequency_Hz"],"target":"下一点的运行通道；只用正常片段拟合","excludeFromFeatures":["anomaly_onset_t","seed","episode_id中的工况/异常编码","未来点"],"contextOnly":{"file":"ESPset-features.csv","esp_id":"真实设备分组编号","label":"Normal / Unbalance / Faulty sensor / Rubbing / Misalignment","peak1x,peak2x,median(8,13),median(98,102),rms(98,102)":"振动速度幅值特征，in/s","a,b":"谱形指数拟合系数","id":"样本号，不是时间戳"}},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"受控工况的时序预测与残差监测","color":"#6b884b","artImage":"assets/images/operations/production-process-v2.webp","artBox":[867,430,286,340]},{"id":"pr5","caseId":"pr5-scaling-risk","stageId":"production","short":"结垢风险","title":"压力与温度一起偏离，能提示节流嘴结垢吗？","question":"相同的真实运行记录，多通道窗口能否比单压力门槛更早发现已标注的变化？","methods":["ts"],"intro":"结垢会改变生产通道的流动条件，压力、温度和气举信号可能随之偏离正常关系。本例从原“结蜡／结垢”场景收窄到有真实标签的生产节流嘴结垢，用Petrobras 3W记录检查异常候选与已标注过程。","problem":"固定压力门槛便于巡检，但正常工况变化也会改变压力。结垢发展时多通道的关系可能先变化，单点越界又未必能说明沉积原因，需要联合记录与事件标注核对。","why":"PCA在正常历史窗口中学习多通道的共同变化，重建残差提示当前窗口是否偏离这组正常关系。与单压力参照并排，学生可以检查联合关系带来的信息，同时识别没有因果证据的风险解释。","input":"按时间排列的P-TPT、P-MON-CKP、T-TPT及可用QGL；保留真实井号、原始时间与采样信息。","output":"正常关系的重建残差、异常分数、候选报警，以及相对0/107/7事件阶段的时间对照。","data":"使用3W Dataset 2.0.0的两段WELL开头实测记录：WELL-00021有46574个秒级点，WELL-00001有76633个。展示可按分钟取传感器中位数；0为正常、107为向结垢发展的过渡、7为已建立的节流嘴结垢，缺失标签单独保留。P-PDG在这两段为全零，不纳入模型。","limits":["标签对应生产节流嘴结垢，不是结蜡、蜡层厚度、井筒任意位置的沉积量或ESP机械故障。","在107过渡期内、7状态之前报警，是识别正在发展的已标注过程；不能写成在事件开始以前预测成功。","压力温度偏离也可能由其他操作造成。残差是风险线索，不证明沉积机理；两段记录的对照不足以代表所有井。"],"experiment":"在同一实测记录上逐步降低异常门槛：原来没有触发的弱候选何时出现？它们落在正常0、过渡107还是事件7？对照单压力基线，较低门槛是否同时增加正常段误报？窗口固定为12分钟。","professional":[{"title":"节流嘴改变流动条件","text":"生产节流嘴通过缩小通道调节流动，运行压力与流体状态相互关联。沉积可能改变有效流通面积，但节流设置、气举和上游条件变化也能产生类似响应，单一压力趋势并不唯一对应结垢。"},{"title":"过渡标签与稳定异常要分开","text":"3W把部分异常的发展过程标为100加事件编号。结垢事件7对应过渡107；这为观察发展过程提供了时间参照。标签为空的区间没有监督结论，不能自动补成正常。"},{"title":"PCA看的是正常关系被怎样打破","text":"正常窗口的主要共同变化可由少数主成分近似重建。当前窗口重建后剩下的差异就是残差，较大残差提示训练时少见的组合；它需要与原始通道、工况和事件阶段一起解释。"}],"steps":[{"name":"收窄风险对象","do":"将目标限定为生产节流嘴结垢过程，分别定义正常0、过渡107和建立事件7；不把结蜡混入标签。","output":"明确的事件对象与时间参照。","blockId":"01"},{"name":"核对通道与单位","do":"选择有记录的压力温度及气举通道，排除全零/全缺列；保留秒级原始资料，分钟展示记录聚合规则。","output":"可用传感器序列、标签及单位表。","blockId":"02"},{"name":"传统：单压力偏移","do":"用训练正常段建立P-MON-CKP参照，以相同的因果顺序给出压力偏移候选。","output":"单通道基线报警与原压力曲线。","blockId":"03traditional"},{"name":"智能：多通道PCA残差","do":"仅用正常历史拟合标准化与PCA，对当前及过去的窗口重建并计算残差，按门槛形成候选。","output":"多通道异常分数及逐通道偏离证据。","blockId":"03intelligent"},{"name":"核对事件阶段","do":"在同一时间轴比较两种候选、0/107/7标签与原通道；统计正常段误报，并分别记录相对过渡和建立事件的时差。","output":"不混淆过渡检出与提前预测的时间对照。","blockId":"04"},{"name":"输出风险复核记录","do":"保存井号、时间、聚合方式、模型参数、残差和事件阶段；现场原因判断继续结合节流操作、取样和除垢记录。","output":"可回到原始来源的结垢风险候选表。","blockId":"05"}],"glossary10":[["结垢","Scaling","无机沉积可能造成通道受限，本例标签限定于生产节流嘴。"],["生产节流嘴","Production choke / PCK","调节生产流动的局部节流部件。"],["气举流量","Gas-lift flow rate / QGL","辅助举升注入的气体流量，本例源单位m³/s。"],["过渡标签","Transient label","3W中100加事件编号标注的发展阶段，本例为107。"],["缺失标签","Missing label","该时段没有参考类别，不自动当作正常。"],["因果窗口","Causal window","只包含当前及更早记录的观察窗口。"],["主成分分析","Principal component analysis / PCA","用少数共同变化方向近似正常多通道结构。"],["重建残差","Reconstruction residual","当前窗口减去模型重建的差异。"],["单通道基线","Single-channel baseline","仅根据一个压力通道建立的比较方法。"],["误报","False alarm","在标注正常时段发出的异常提示。"]],"primarySource":{"title":"Petrobras · 3W Dataset 2.0.0","url":"https://github.com/petrobras/3W","license":"数据CC BY 4.0；工具代码Apache-2.0。本例只选WELL实测文件。"},"research":{"title":"3W Dataset 2.0.0: a realistic and public dataset with rare undesirable real events in oil wells","url":"https://arxiv.org/abs/2507.01048","summary":"作者公开多变量油井运行时间序列及专家事件阶段标签，并在文件来源中区分实测、仿真和手绘实例。","boundary":"本课只取两段实测节流嘴结垢记录，重新建立因果PCA残差与单压力对照；不沿用文献成绩，也不把其他异常都解释为结垢。"},"columnMap":{"files":["3w-scaling-WELL-00021_20180611011218.parquet","3w-scaling-WELL-00001_20170226130146.parquet"],"input":{"index":"源时间戳；原文件未明确时区，不额外声称UTC","P-TPT":"水下树压力，Pa；显示可除以10^6换成MPa","P-MON-CKP":"生产节流嘴上游压力，Pa","T-TPT":"水下树温度，°C","QGL":"气举流量，m³/s；仅在有效时使用"},"target":{"class":"0正常、107过渡、7建立事件、空值未知，仅供评价"},"meta":{"filename":"WELL来源和井号","state":"运行状态标签，仅作核对，不入模型"},"excludeFromFeatures":["class","state","P-PDG（本例全零）","全缺通道","未来窗口"],"derived":"分钟显示取传感器中位数、标签取非缺失众数；精确起点和延迟应回到原秒级标签。"},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"正常工况PCA残差监测","color":"#3a8c8a","artImage":"assets/images/operations/production-process-v2.webp","artBox":[1159,430,287,340]},{"id":"wo1","caseId":"wo1-plan","stageId":"workover","short":"修井方案","title":"相似的修井方案，为什么还要核对井况？","question":"用中文描述井况，能否找到有出处的相似方案，并看清哪些条件尚未满足？","methods":["kg","nlp"],"intro":"修井是在已有井筒和完井系统上恢复通道、处理故障或更换部件。一次检索可以找到历史申报里相近的作业，但“文字相像”与“当前井可采用”是两个判断。本课先找证据，再用图谱展示井、计划与作业类型之间的关系。","problem":"井史里常混用设备简称、作业代码和自然语言。同样写着套压、油管或阀门问题的记录，可能对应不同井身结构与作业目标；只搜一个关键词容易漏检，也容易把相似措辞当作相同工况。","why":"TF-IDF将记录变成术语权重向量，余弦相似度适合建立可以逐词解释的检索基线。显式中英词表使中文问题与英文申报字段对齐；知识图谱保留记录、井号、作业代码和来源边，工程约束负责把不适用或信息不足的候选单独标出。","input":"中文或英文查询、已知井况条件，以及真实申报的井号、日期、官方作业代码和简短文本。","output":"有来源链接的候选计划、命中术语、相似度排序，以及约束满足、冲突或缺信息的证据清单。","data":"课堂来源子集有295条真实BSEE修井申报、31口井，其中165条含原始短说明；本例检索进一步取20份归一化计划字段作为语料，提供3个教学问题。文字由官方作业代码与原文检出的事实术语组成，网站不发布原文片段，可回BSEE原计划核对。申报计划不等于完整井史或已验证的修井结局。","limits":["余弦相似度只是文本相关程度，不能解释为修井成功率或安全概率。","公开记录没有统一的“故障—工具组合—现场结果”标签；图谱只添加来源能够支撑的边。","同一井可能多次申报或延期。相同措辞的计划必须识别为重复证据，不能充当多次独立成功案例。","缺少井筒通径、部件状态或设备参数时，保留“待补充”，不能由语言模型猜出适用结论。","为形成同井历史，子集选择重复申报较多的井，套管压力类记录较多；检索空缺也可能来自资料覆盖。"],"experiment":"先用“套管压力异常，需要查类似处理记录”检索，再加入“油管更换”等条件。比较只看关键词、TF-IDF排序和来源图谱后，哪些候选上升、被排除或需要补资料；换一个同义中文问法，检查英文术语是否一致。","professional":[{"title":"修井方案是一项有条件的计划","text":"一份申报同时包含作业对象、井况、设备条件和预定工作。Change Tubing、Casing Pressure Repair等代码便于归档，却不说明故障已被确诊，也不证明计划已经实施。案例把“计划里写了什么”与“现场发生了什么”分开显示。"},{"title":"检索把问题缩小，图谱把证据接起来","text":"中文“油管”可映射到tubing、tbg；“井下安全阀”可映射到SCSSV、SSSV。映射词表公开展示，便于发现歧义。图谱中的“计划属于某井”“计划包含某作业代码”来自真实外键，不把自动联想写成新的工程事实。"},{"title":"相关性需要经过适用条件检查","text":"文本相似的记录仍可能使用不同井筒结构、不同更换对象或不同设备。工程条件可用于排除冲突；未知条件只意味着证据不足。一次检索的合格终点是可追溯的候选资料与核对项目，而不是自动批准一个作业程序。"}],"steps":[{"blockId":"01","name":"明确要找哪类历史证据","do":"写出问题、已有井况和必须核对的条件，约定输出为候选资料及证据，而非成功概率。","output":"查询意图、已知条件和缺失条件表。"},{"blockId":"02","name":"连接计划、井号与作业代码","do":"按SN_APM连接主表、说明与子作业表，保留API井号和申报日期，合并同井同计划日期的重复记录。","output":"可追溯的检索文档及来源关系。"},{"blockId":"03traditional","name":"传统：关键词与代码筛选","do":"用固定关键词和官方作业代码筛选，记录同义词漏检和泛化措辞带来的误检。","output":"关键词候选及命中依据。"},{"blockId":"03intelligent","name":"智能：文本排序与证据图谱","do":"显式映射中英术语，用训练语料拟合TF-IDF并计算余弦相似度；结合来源图谱检查已知工程约束。","output":"候选排序、命中术语和满足／冲突／未知状态。"},{"blockId":"04","name":"核对查询与原始记录","do":"逐条打开来源，检查作业目标是否相关、图谱边是否有据；同井与重复措辞不能跨组制造容易的检索题。","output":"人工核对的相关性记录与失配原因。"},{"blockId":"05","name":"形成可复核的资料包","do":"保存查询、词表版本、候选ID、来源链接和待补资料，让工程人员能够复查检索过程。","output":"带证据路径的历史方案候选清单。"}],"glossary10":[["修井","Workover","在已有井筒和完井系统上进行修复、调整或更换的作业。"],["作业申报","Application for Permit to Modify","BSEE记录计划或变更工作的行政资料，不等于实施结局。"],["井号","API well number","连接同一井多次申报的标识，不作为预测结果的输入捷径。"],["作业代码","Suboperation code","官方字典中的分类，例如更换油管或套管压力处理。"],["术语映射","Query expansion","把中文与英文简称连接起来，使同义表达进入同一检索范围。"],["词频—逆文档频率","TF-IDF","突出单条记录里较有辨识度的词语的加权表示。"],["余弦相似度","Cosine similarity","比较两个文本向量方向的相关性分数，不能当成功率。"],["知识图谱","Knowledge graph","用节点和有类型的关系记录计划、井、作业代码及来源。"],["工程约束","Engineering constraint","用于核对适用条件的要求；缺少必要参数时结论保持未知。"],["证据溯源","Provenance","从候选结果回到原始申报ID、字段与发布来源的路径。"]],"primarySource":{"title":"BSEE eWell修井申报事实数据","url":"https://www.data.bsee.gov/Well/eWellAPM/Default.aspx","license":"联邦事实数据；机构原创材料通常属公有领域。第三方作业叙述不自动取得开放许可，课堂使用规范化事实文本与来源链接。"},"research":{"title":"BC Energy Regulator：Completion / Workover Report参考指南","url":"https://www.bc-er.ca/files/operations-documentation/Oil-and-Gas-Operations-Manual/Supporting-Documents/Notice-of-Operations-and-Completion-Workover-Report-Reference-Guide.pdf","summary":"监管指南将修井、完井和日常维护按具体工作区分，说明作业名称背后有明确的对象与报告边界。它为本课解释作业分类提供真实依据。","boundary":"该指南属于加拿大BC监管环境，不能把其报告要求直接套入BSEE数据，也没有给出本课检索模型的性能。"},"columnMap":{"file":"assets/operations/data/wo1.json","recordPath":"model.documents[]；来源行为bsee-workover-plan-sequences.json","input":{"text":"由真实作业代码和原文检出词构成的规范化文本","vector":"经L2归一化的TF-IDF文档向量","model.queryTermMap":"显式中英词表；查询使用同一组固定IDF"},"target":{"records[].target":"null：没有独立标注的相关性或打捞成功标签"},"meta":{"id":"原始SN_APM","wellApi":"API井号","submittedAt":"来源申报时间，不擅自附加UTC标记","suboperationCodes":"官方关联作业代码","sourceUrl":"BSEE原始记录链接"},"excludeFromFeatures":["sourceDescriptionSnippet","estimatedDays","id","wellApi","sourceUrl"],"derived":"score等于归一化查询与文档向量的逐项乘积之和；代码筛选不是井况物理适配判断。"},"backgroundChapters":[{"id":"context","title":"真实情境","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放依据","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难点与边界","fields":["limits"]},{"id":"glossary","title":"中英术语速查","fields":["glossary10"]}],"algorithm":"TF-IDF文本检索＋来源知识关联","color":"#b95739","artImage":"assets/images/operations/workover-process-v2.webp","artBox":[4,430,294,360]},{"id":"wo2","caseId":"wo2-fishing","stageId":"workover","short":"打捞选型","title":"一个落物，为什么不能只按名称选打捞工具？","question":"当落物内外径、井筒通径和可抓持部位变化时，哪些工具仍满足已知条件？","methods":["kg"],"intro":"“落物”可以是管柱、工具、钢丝或小块杂物，外形与可接近的抓持面不同。选型首先要回答工具能否通过井筒、能否接触并抓住落物，再核对具体型号的适用范围。课堂把这些要求画成可解释的工具知识图谱。","problem":"只凭“油管掉落”或“井底杂物”这样的名称，无法判断外抓、内抓或收集工具是否合适。名义套管尺寸也不等于全井最小通径；一个尺寸满足的工具仍可能缺少可抓持表面、解脱能力或必要的额定参数。","why":"知识图谱适合表示“工具家族—抓持对象—尺寸约束—资料来源”的离散关系。确定性的几何检查可以逐条解释排除原因，并把尚无证据的参数保留为未知，让选型结果随输入条件透明变化。","input":"落物类别、外径和内径、可接近的抓持面、材料信息；井筒最小通径与课堂指定间隙；有出处的工具规格。","output":"各候选的约束核对卡、排除原因或缺失证据，以及工具与落物的简化几何关系图。","data":"工具家族参考NOV Bowen、SLB等一手资料。本例含5组明确标为DEMO的教学尺寸，用来观察通径与抓取约束；另列3条真实Bowen打捞篮目录规格。6635N列有3¾—4英寸适用井径、3⅝英寸筒体外径和2¼英寸最大落物直径；筒体外径不是完整总成最大外径，相关核对保留缺证据。不含现场成功率标签。","limits":["兼容性表示满足已列条件，不表示落物一定能够回收。","实际井筒最小通径、抓持表面和负载参数缺失时，结果必须显示缺信息。","径向间隙是课堂显式输入，不能把演示值称为通用工程容差。","厂家型号、额定载荷和解脱方式必须逐项溯源，不能把一个型号的规格推广到整个工具家族。"],"experiment":"固定同一个管状落物，逐步减小井筒内径或增大自选径向间隙，观察外捞筒与内捞矛怎样被保留或排除。再切换到抓取面未知、小件杂物等情景，区分“不满足”和“缺证据”，核对真实目录与DEMO尺寸的来源。","professional":[{"title":"外抓、内抓与收集处理不同对象","text":"Overshot从落物外侧抓持管状或工具表面；spear在适用内径中从内部抓持。反循环打捞篮利用其结构收集小而不规则的杂物。图谱先比较抓持机制，再核对型号尺寸，避免让“打捞工具”成为没有差别的一个标签。"},{"title":"通径检查与抓持检查是两道条件","text":"工具外径加两侧所需间隙不得超过已知最小通径，是本课的几何筛选。通过该检查后，还要判断卡瓦或抓持机构能否覆盖落物对应的内径或外径范围。管柱弯曲、局部缩径等未给出的现场条件不由示意图推断。"},{"title":"资料不足应当成为可见结果","text":"“金属”不等于“已确认铁磁性”，“有解脱结构”也不代表任何载荷下都可操作。本课把未确认材料、尺寸、额定载荷和适用条件显示为未知；每个通过或排除的判断都能回到规格来源。"}],"steps":[{"blockId":"01","name":"描述落物与通道","do":"区分管状落物、小杂物和钢丝，列出可抓持部位、已知尺寸及必须确认的参数。","output":"带未知值的落物与井筒条件表。"},{"blockId":"02","name":"整理有出处的工具规格","do":"按具体型号记录外径、抓持范围、适用井径与来源，将英寸统一换算为毫米。","output":"带型号和版本的工具节点。"},{"blockId":"03traditional","name":"传统：按名称查目录","do":"根据落物名称找工具家族，再人工翻查尺寸；标记名称相符却尺寸或抓持面不符的候选。","output":"目录候选与人工核对结果。"},{"blockId":"03intelligent","name":"智能：图谱逐条检查约束","do":"依次检查通径、抓持面和型号范围，对每条条件输出满足、冲突或未知，连接相应来源。","output":"可解释的约束矩阵与几何图。"},{"blockId":"04","name":"验证边界与缺失信息","do":"测试刚好达到尺寸上限、单位转换和未知材料等情形；比较图谱结果与原始规格。","output":"边界案例及证据缺口记录。"},{"blockId":"05","name":"保存选型依据","do":"记录输入条件、规格链接、通过条件和待确认项目；适用结论只覆盖已经检查的范围。","output":"可交给工程人员复核的候选资料单。"}],"glossary10":[["落物","Fish","遗留或卡在井中的管柱、工具及其他待回收物。"],["打捞筒","Overshot","从落物外侧抓持的工具家族，具体范围由型号规定。"],["打捞矛","Spear","进入适用的落物内孔并从内部抓持的工具家族。"],["卡瓦","Grapple / slips","与落物接触并提供抓持作用的机构。"],["反循环打捞篮","Reverse-circulation junk basket","面向小而不规则杂物的收集工具，受适用尺寸限制。"],["外径","Outside diameter","物体外表面的直径，通道与抓持检查需要区分其所属对象。"],["内径","Inside diameter","管状落物内孔的直径，是内抓工具的重要条件。"],["最小通径","Minimum restriction diameter","沿通过路径能够确认的最小可通尺寸，不等于名义套管尺寸。"],["铁磁性","Ferromagnetism","材料可被相应磁性工具吸引的性质，不能仅由金属外观推断。"],["解脱能力","Release capability","工具设计中可解除抓持的能力，需核对具体型号条件。"]],"primarySource":{"title":"NOV Bowen反循环打捞篮型号规格","url":"https://assets.nov.com/NCP4N68N/at/ww4s788t6pn6v6t97sjsp7x/Bowen_Reverse_Circulation_Junk_Baskets_Tool_Specification.pdf","license":"厂家资料保留版权；引用少量型号事实并链接原件，课堂几何示意重新绘制。"},"research":{"title":"SLB Energy Glossary：Overshot","url":"https://glossary.slb.com/terms/o/overshot","summary":"一手工具定义说明打捞筒在落物外表面抓持，并介绍可解脱设计的作用，为工具—抓持面关系提供明确依据。","boundary":"工具定义没有提供不同井况下的回收成功率，也不能替代具体型号的尺寸、材料与载荷资料。"},"columnMap":{"file":"assets/operations/data/wo2.json","recordPath":"model.tools[]与records[].input","input":{"fish.outsideMm":"落物外径，mm","fish.insideMm":"落物内径，mm","fish.outsideAccessible":"外抓表面是否已确认可接近；null表示未知","fish.insideAccessible":"内孔是否已确认可进入；null表示未知","well.minimumIDmm":"路径最小通径，mm","well.radialClearanceMm":"课堂显式指定的径向间隙，mm"},"target":{"records[].target":"逐工具约束状态：1满足、0排除、-1缺证据；不是成功概率"},"meta":{"model.tools[].kind":"published-catalog为真实目录事实；controlled-synthetic为明确教学尺寸","model.tools[].barrelODmm":"已核实Bowen筒体外径，不改称完整总成最大外径","model.tools[].assemblyODmm":"教学夹具明确给出的总成外径；真实打捞篮该值未知","sourceUrl":"原始尺寸规格链接"},"excludeFromFeatures":["invented field success probabilities","nominal casing size substituted for measured restriction","unknown values filled with zero"],"derived":"总成外径+2倍径向间隙不超过最小通径；真实目录篮保留总成尺寸缺证据状态。1英寸精确等于25.4mm。"},"backgroundChapters":[{"id":"context","title":"真实情境","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放依据","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难点与边界","fields":["limits"]},{"id":"glossary","title":"中英术语速查","fields":["glossary10"]}],"algorithm":"工具尺寸与可抓取条件图谱","color":"#497d99","artImage":"assets/images/operations/workover-process-v2.webp","artBox":[306,430,272,360]},{"id":"wo3","caseId":"wo3-casing","stageId":"workover","short":"超声壁厚","title":"超声回波变了，CNN识别到的是壁厚还是管径？","question":"在同一组公开超声仿真波形上，回波间隔基线与二维CNN能否估计未参与训练管径的壁厚？","methods":["cv"],"intro":"套管超声检测从管内发射脉冲，分析管壁反射与后续振铃来估计壁厚等参数。现场图像还受流体、偏心和管外介质影响。课堂使用有物理真值的公开COMSOL波形，将其变成时频图，检验图像模型有没有只记住训练管径。","problem":"壁厚变薄会改变回波和共振特征，但相似变化也可能来自管径、探头位置和材料条件。直接把颜色斑块标成腐蚀，容易把成像差异当作缺陷；同一仿真条件的相邻样本若随机分散到训练和测试，也会夸大泛化能力。","why":"短时傅里叶变换将回波随时间变化的频率结构变成二维输入，CNN可以组合局部时频纹理。物理回波间隔提供可解释对照；整组管径留出则检验模型能否把壁厚关系迁移到不同几何条件，而不是记住样本外观。","input":"公开仿真的单条超声A扫描、采样间隔和受控几何信息；训练目标为模型已知的壁厚。","output":"回波间隔基线与CNN的壁厚估计（mm）、对同一波形的误差，以及留出管径的整体评估。","data":"数据来自Diez等公开CC BY 4.0超声井完整性仿真。课堂选72条2.5D管模型波形，三个外径组各24条，管内油基泥浆、管外水泥且无间隙；波形为归一化幅值，壁厚真值以米记录。BSEE实测结构套管UT报告可作拓展情境，未进入这些模拟波形的训练或检验。","limits":["这些波形由COMSOL生成，是公开科学仿真，不是现场多臂井径或井下超声图像。","原始监督目标是连续壁厚；数据没有经现场证实的腐蚀、裂纹或变形类别。","72条受控样本足够观察教学方法差异，不能证明CNN已经具备现场诊断能力。","时频图由本课变换生成。若拼接为二维扫描示意，必须标明构造顺序，不能称为真实井周图。","回波重叠或周期选错会使物理基线失效；CNN误差也需按管径、厚度和输入边界解释。"],"experiment":"切换留出管径组中不同壁厚的波形，比较回波间距参照与CNN壁厚候选。固定一条波形后，改变自选名义厚度或减薄筛查线：为什么估计壁厚保持不变，复核标记却可能改变？时频图、原波形和源模型壁厚必须始终对应同一记录。","professional":[{"title":"壁厚与回波周期有物理联系","text":"当能够识别相邻的管壁往返回波时，壁厚近似为钢中纵波速度乘往返时间间隔的一半。薄壁通常对应更短的往返周期。实际脉冲有带宽、多个反射相互重叠，载波周期也可能被错认成壁内往返周期，因此基线需要给出选窗和峰间隔依据。"},{"title":"时频图的颜色需要有一致含义","text":"STFT图横轴是时间，纵轴是频率，颜色表示同一规范下的幅值或相对能量。本课从归一化A扫描生成图像，不能恢复绝对声压。训练与测试须使用同样采样、窗口、归一化和颜色尺度，图中文字、文件名与壁厚标签不进入模型。"},{"title":"真实测厚网格是独立情境","text":"BSEE 2024-01给出事故后回收的20英寸结构套管测厚网格，区分有效读数、孔洞和无法测量的位置。它显示壁厚空间分布为何值得关注，但对象是水面附近结构套管，而且只有一个案例；不能把它当作井下扫描训练集或CNN现场检验。"}],"steps":[{"blockId":"01","name":"把识别目标限定为壁厚","do":"确定输出是连续壁厚，不把薄壁自动改写成腐蚀类别；预先指定整组管径的训练、验证与测试角色。","output":"壁厚任务定义和几何留出方案。"},{"blockId":"02","name":"从A扫描生成统一时频图","do":"读取t0、dt和波形，核对米到毫米的换算；按固定窗口计算STFT，保留原波形与文件ID。","output":"时域波形、时频图和独立保存的厚度真值。"},{"blockId":"03traditional","name":"传统：回波间隔估厚","do":"在预先声明的回波窗内寻找合理往返间隔，结合声速求厚度；标注周期歧义或无法估计的样本。","output":"带选窗依据的物理基线厚度。"},{"blockId":"03intelligent","name":"智能：二维CNN回归厚度","do":"仅用训练管径的时频图拟合小型CNN，使用验证管径调节训练参数，再冻结模型。","output":"CNN壁厚估计与训练／验证曲线。"},{"blockId":"04","name":"比较整组留出管径","do":"在相同测试波形上比较两种方法，报告毫米MAE、逐样本误差和失败比例，不以训练拟合代替测试。","output":"管径留出误差表和误判样本。"},{"blockId":"05","name":"保留变换与来源边界","do":"保存原始文件ID、STFT参数、划分与模型设置；将BSEE实测网格放在独立情境卡中。","output":"可复现的超声壁厚教学实验记录。"}],"glossary10":[["A扫描","A-scan","单个探测位置的回波幅值随时间变化的记录。"],["脉冲回波","Pulse echo","发射超声脉冲并分析返回信号的测量方式。"],["壁厚","Wall thickness","本课的连续预测目标，原始真值以米记录。"],["振铃","Ringdown","反射后持续出现的振荡结构，包含壁厚及介质相关信息。"],["往返时间","Round-trip time","声波在管壁内往返所用时间，正确识别后可与壁厚联系。"],["短时傅里叶变换","Short-time Fourier transform","通过滑动时间窗形成时间—频率表示。"],["时频图","Time-frequency image","由波形变换得到的二维图，不是原始井周成像。"],["卷积回归","CNN regression","由图像特征输出连续数值，本课输出壁厚。"],["管径留出","Diameter-group holdout","同一外径的所有样本只放在一个划分中。"],["微环隙","Microannulus","管壁与外部材料间的薄间隙，本课堂子集不含该变化。"]],"primarySource":{"title":"Diez等：Simulated ultrasonic pulse-echo well-integrity dataset","url":"https://data.mendeley.com/datasets/3bs65nzpv2/1","license":"CC BY 4.0；保留作者、DOI、许可链接与本课STFT变换说明。"},"research":{"title":"Ultrasonic pulse-echo dataset from numerical modelling for oil and gas well integrity investigations","url":"https://www.nature.com/articles/s41597-025-04851-x","summary":"研究用可控制的管径、壁厚、介质和偏心等条件生成超声波形，并给出物理参数真值，使算法能够区分几何与材料变化的影响。","boundary":"论文提供数据与数值模型依据，没有证明本课STFT二维CNN已通过现场验证。研究中的仿真性能与课堂留出测试结果也必须分别报告。"},"columnMap":{"file":"mendeley-json/*.json","recordPath":"单个原始JSON；选择清单见mendeley-selected-manifest.json","input":{"waveform.values":"归一化无量纲回波幅值","waveform.t0":"起始时间，s","waveform.dt":"采样间隔，s","waveform.sample_no":"样本数量"},"target":{"interface.thickness":"壁厚，m；输出乘1000换为mm，仅作为监督目标"},"meta":{"interface.outer_diameter":"外径，m；用于整组划分","general.geometry":"必须为pipe，不能把plate当套管","inside.transducer_pipe_distance":"探头到壁面距离，m","interface.vp":"材料纵波速度，m/s；用于物理基线","outside.material":"本子集为cement"},"excludeFromFeatures":["interface.thickness","原始file_ID","文件名","带有真值的文字或色条","仅因标签而决定的图像窗口"],"derived":"A扫描按同一STFT流程生成二维图；训练、验证、测试分别使用不同的整个外径组。"},"backgroundChapters":[{"id":"context","title":"真实情境","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放依据","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难点与边界","fields":["limits"]},{"id":"glossary","title":"中英术语速查","fields":["glossary10"]}],"algorithm":"超声时频图CNN测厚","color":"#8b65a0","artImage":"assets/images/operations/workover-process-v2.webp","artBox":[589,430,271,360]},{"id":"wo4","caseId":"wo4-risk","stageId":"workover","short":"过程预警","title":"压力和扭矩升高时，怎样区分换工序与异常？","question":"只利用当前和过去的数据，按工序建立的残差监视器能否降低误报，同时及时发现持续偏离？","methods":["ts"],"intro":"修井过程中的压力和扭矩会随工序变化，正常升压或旋转作业本身就会带来突变。一个把全程混在一起的阈值很容易在换工序时报警。课堂用明确标注的合成作业段，学习在已知工序中监视偏离，并查看误报与漏报之间的取舍。","problem":"连续信号有噪声、漂移、阶段切换和传感器问题。单点越限不一定代表持续异常，整段平均又可能掩盖早期变化；如果使用未来窗口或异常标签选择基线，回放中看似提前的预警在现场并不能实现。","why":"时序方法可以为不同工序拟合正常水平与波动，再对因果预测残差进行平滑和持续性判断。阶段标签来自作业过程而不是异常答案，基线只用正常训练段，使每次报警都能说明是哪个通道、哪个时间窗超出参考波动。","input":"带时间戳的压力、扭矩与已知工序；完整作业段的训练、验证和测试划分。","output":"实时可计算的残差、报警时间和持续区间，以及相对合成异常起点的检出延迟、漏报和误报统计。","data":"课堂时间序列全部由显式教学生成器合成，包含工序正常变化、漂移、噪声和预设异常起点。压力与扭矩用注明的演示单位呈现，数值不是现场操作限值。BSEE真实事故报告只提供修井设备、工况与前期核对的重要情境，不被伪装为传感器数据。","limits":["本实验没有已核验的现场高频压力—扭矩数据，所有预警成绩只属于模拟。","异常注入标签表示生成器设定的事件，不等于现场确认的卡阻、井控或设备故障诊断。","改变阈值只改变教学检测器的行为，不能据此制定真实设备或井筒的安全限值。","事件已经发生后才响起的是延迟检出；只有确有先兆标签时才可称提前量。"],"experiment":"固定一个模拟作业段，检查全程水平参照与分工序残差监测在正常换工序时的差异。再改变残差门槛和连续点数，同时核对当前片段的漏标点与多标点；窗口和拟合参数固定，整组检验成绩不随滑杆重算。","professional":[{"title":"工序是正常行为的上下文","text":"同一压力读数在循环、起下管柱或旋转等阶段中的含义并不相同。课堂将阶段作为生成器公开的过程信息，先在每个阶段估计正常水平，再判断相对偏离；模型不能读取注入异常的起止位置来识别工序。"},{"title":"因果监视只能使用已经到达的数据","text":"时刻t的残差、滚动统计与平滑值只能依赖t及以前的样本。居中移动平均会借用未来信号，回放时容易造成虚假的提前响应。训练所用正常段与验证阈值分开，并在独立作业段检查最终表现。"},{"title":"持续性与事件统计共同决定效果","text":"要求连续多个点异常可以过滤短促噪声，却也增加检出延迟。评价时应合并相邻报警为事件，统计每段误报、检出的注入事件和起点后的延迟；逐点准确率容易被大量正常样本抬高，不能单独说明预警是否有用。"}],"steps":[{"blockId":"01","name":"定义可检出的合成事件","do":"说明工序、通道与注入事件的含义，约定何时算报警、怎样合并相邻报警及怎样计算延迟。","output":"公开的事件规则与评价口径。"},{"blockId":"02","name":"生成并分开完整作业段","do":"记录生成器参数和随机种子，保留真实时间顺序；完整作业段及其种子不跨训练、验证、测试。","output":"有来源标记的合成序列与划分。"},{"blockId":"03traditional","name":"传统：全程固定阈值","do":"用同一组训练／验证条件设定简单越限检查，观察换工序与短噪声产生的报警。","output":"固定阈值基线与误报区间。"},{"blockId":"03intelligent","name":"智能：按工序监视因果残差","do":"只用正常训练段拟合阶段参考，计算单向滚动残差并按持续性发出报警；参数由验证段选择。","output":"残差曲线、报警时刻与触发通道。"},{"blockId":"04","name":"按事件核对测试结果","do":"在冻结参数的测试作业段统计漏检、每段误报和检出延迟，逐个核对报警原因。","output":"事件召回、误报和延迟的完整结果。"},{"blockId":"05","name":"保存监视器与模拟边界","do":"保存参数、生成种子、作业段ID和报警记录，将模拟结果与真实BSEE情境分别标注。","output":"可复现的因果时序监视实验。"}],"glossary10":[["工序","Operation phase","解释当前信号正常范围的过程阶段。"],["压力","Pressure","本课合成通道之一，演示量值不代表现场操作限值。"],["扭矩","Torque","旋转作用相关量，本课只用于合成过程监视。"],["正常基线","Normal baseline","由正常训练段形成的参考水平与波动。"],["因果窗口","Causal window","仅包含当前与历史样本的统计窗口。"],["预测残差","Prediction residual","观测值与因果参考或预测之间的差。"],["漂移","Drift","信号水平缓慢改变，可能带来基线失配。"],["持续性条件","Persistence condition","要求偏离持续若干点再报警的规则。"],["事件召回","Event recall","被检测到的注入异常事件占所有注入事件的比例。"],["检出延迟","Detection delay","从事件开始到首次有效报警的时间，不能误称提前量。"]],"primarySource":{"title":"真实修井情境：BSEE 2024-01液压修井设备事故调查","url":"https://www.bsee.gov/panel-investigation/investigation-of-march-25-2022-hydraulic-workover-unit-failure-fatality","license":"联邦调查资料；第三方图片各自保留权利。课堂传感器序列独立合成，不冒充报告实测数据。"},"research":{"title":"BSEE Panel Report 2024-01：设备、工况与作业准备","url":"https://www.bsee.gov/sites/bsee.gov/files/2024-08/MP%2064%20No-19%20Report%2030May24.pdf","summary":"真实调查把修井设备、结构套管状态、装配经过和职责核对联系起来，说明风险判断必须结合工作情境与证据。","boundary":"报告没有可用于本实验的连续压力—扭矩波形，没有验证残差监视器，也不能据此推出报警阈值或提前预警成绩。"},"columnMap":{"file":"assets/operations/data/wo4.json","recordPath":"records[].display；原始教学生成器见prepare-workover.py","input":{"input":"默认光标处10维因果特征，不包含当前实测目标","display.batchInputs":"238个时序输入，分别对应t=2至239","display.values[t][0]":"教学合成压力，MPa","display.values[t][1]":"教学合成扭矩，kN·m","display.values[t][2]":"教学合成载荷，kN","display.phase":"已知工序上下文，不由异常答案反推"},"target":{"target":"当前光标处三通道值，供预测核对","display.pointTruth":"注入的逐点答案，不能进入输入","display.events":"注入事件起止与类别，只用于评价"},"meta":{"sourceId":"完整作业段的生成种子","kind":"必须为controlled-synthetic","display.timeS":"段内时间，s","display.cursor":"默认光标位置","model.phaseMeans":"只由正常训练段计算的工序参考"},"excludeFromFeatures":["display.pointTruth","display.events","current observed target","future sensor values","centered moving windows"],"derived":"用工序与前两点残差向量预测当前值；按正常训练残差标准差计算z分数。单向EWMA在换工序时重置；阈值和持续点数均为教学参数。"},"backgroundChapters":[{"id":"context","title":"真实情境","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放依据","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难点与边界","fields":["limits"]},{"id":"glossary","title":"中英术语速查","fields":["glossary10"]}],"algorithm":"分工序自回归＋持续残差监测","color":"#6b884b","artImage":"assets/images/operations/workover-process-v2.webp","artBox":[867,430,286,360]},{"id":"wo5","caseId":"wo5-duration","stageId":"workover","short":"计划工期","title":"过去的修井计划，能估下一次申报的工期吗？","question":"只用此前已提交的同井计划，下一份计划的申报工期估计能否比沿用上次或历史中位数更准确？","methods":["ts"],"intro":"排修井计划需要估计占用时间，但计划值与实际完工时间是不同数据。公开BSEE申报提供了真实的日期、井号和预计天数，适合学习同井行政事件序列的预测。本课明确预测下一份计划的申报预计工期，不把它称为已实现的修井周期。","problem":"同一井会重复申报、延期或修改计划，开始日期并不一定是实际开工日。若把审批表中的预计天数当真实工期，或把周报起止日期相减，模型的目标就已经定义错误；随机拆分还可能把同一计划的修订本泄漏到测试集。","why":"时序方法可以把此前计划的预计天数作为历史，检验持续性、趋势和同井差异是否有预测价值。简单的上次值与历史中位数提供必要基线；独立CHECK记录的绝对误差形成可核对的历史误差范围，随后再用TEST记录检查覆盖。","input":"同井严格更早提交的计划日期与预计天数；预测时已经知道的作业上下文另行标明。","output":"下一份申报计划预计天数的中央估计、独立CHECK误差范围、历史基线，以及按日期留出的误差与范围覆盖。","data":"原始修井表有6265条计划；6240条具备可解析日期和正预计天数。按同井同计划开始日保留最早申报后有3920条，56口井至少6条。课堂选295条、31口井，每井7—16条，按全局申报日期划分177／59／59；有至少两条更早历史的预测点共233个，对应123个训练、54个检查、56个测试；54个检查再按时间分27个选模与27个独立CHECK校准。字段EST_OPERATION_DAYS明确表示预计天数，没有实际完工标签。","limits":["目标是申报的计划工期估计，不是现场实际耗时、完工日期或资源消耗。","不同计划开始日期仍可能属于同一作业的延期或修订，不能把295条记录称为295次独立完成的修井。","该序列间隔不规则，不能插值成每日修井工期后再当真实观测建模。","使用先前已揭示标签作滚动历史时，要说明是逐次预测协议；模型权重不能用测试期标签重新拟合。","计划值常按整天或常用天数填写。较小误差也可能来自稳定申报习惯，不证明实际作业更可控。","子集为获得足够历史而选择多次申报井，171条带套管压力处理代码；结果不代表全部修井类型。"],"experiment":"选择具备较长历史的同井计划，逐步减少当前可见的过去申报条数，比较GRU中央估计、上次值和随后申报天数。核对每条历史提交时间均早于目标，理解CHECK误差范围在后续TEST计划中为何可能覆盖不足。","professional":[{"title":"先核对“天数”究竟指什么","text":"BSEE表中的EST_OPERATION_DAYS对应申报预计工期。公开A-24号井ESP与油管更换许可写有预计5天，这个数字说明计划如何填写，并没有证明作业5天完成。周报WAR_START_DT、WAR_END_DT则是报告覆盖期，二者相减同样不能获得修井实际工期。"},{"title":"行政事件序列有历史，也有修订","text":"以SUB_STAT_DATE排列，能够确定哪份申报先于当前记录出现。API井号连接同井历史；计划开始日只作分组与核对。课堂把同井同计划开始日的重复组压为最早申报，仍保留重复数量和日期异常标记，提醒后续延期可能没有被完全合并。"},{"title":"历史误差范围也需要后续核验","text":"GRU的P50输出作为中央估计。54个有效验证点按日期分为27个选模型点和27个独立CHECK点；模型冻结后，取CHECK绝对P50误差的向上80%经验分位数作为对称半宽。再检查56个TEST点的覆盖率。这只是过去CHECK误差范围，不保证新计划有80%条件覆盖，更不是实际按期完工概率。原始分位数交叉问题单独保留审计。"}],"steps":[{"blockId":"01","name":"把工期目标写清楚","do":"确认标签来自EST_OPERATION_DAYS，定义为下一份申报预计天数，并说明没有实际完工记录。","output":"目标字段与可回答问题的边界。"},{"blockId":"02","name":"按可知时间整理同井历史","do":"保留井号、申报时间与计划开始日，压缩同井同计划日期的重复组；只把严格更早提交的计划加入历史。","output":"带重复标记的有序计划事件序列。"},{"blockId":"03traditional","name":"传统：上次值与历史中位数","do":"在每个预测时点用此前记录给出两条简单基线，前两条仅用于历史预热。","output":"无需未来信息的工期基线。"},{"blockId":"03intelligent","name":"智能：拟合序列并校对历史误差","do":"只在训练期拟合GRU，用较早验证点选模型；冻结后以独立CHECK点的绝对P50误差确定范围半宽。","output":"下一份计划的中央估计与独立CHECK误差范围。"},{"blockId":"04","name":"用后续申报核对预测","do":"按全局时间留出检查中央估计MAE、CHECK误差范围的TEST覆盖与宽度；已揭示记录可更新历史，不可用TEST拟合权重或半宽。","output":"有单位、时序协议与样本数的评估。"},{"blockId":"05","name":"保存预测条件与数据审计","do":"保存井号、目标计划ID、每次可用历史、划分日期和重复规则，把“计划值”标记保留在结果与导出中。","output":"可复核的计划工期预测及适用边界。"}],"glossary10":[["计划工期","Estimated operation duration","申报中预计占用的天数，是本课监督目标。"],["实际工期","Actual elapsed duration","由真实开始和结束证据定义的耗时，本数据未提供。"],["申报时间","Submission timestamp","决定哪些记录在预测时点之前已经存在的日期时间。"],["计划开始日","Planned commencement date","计划拟开始的日期，不是经过核验的实际开工日。"],["行政事件序列","Administrative event sequence","按申报时间排列的计划记录，间隔不规则且可能有修订。"],["滞后特征","Lag feature","只从更早计划的预计天数构造的历史输入。"],["逐次预测","Walk-forward evaluation","先预测后揭示答案，再把已知过去加入后续历史的检验方式。"],["时间留出","Chronological holdout","较早记录用于训练，较晚记录用于验证或测试。"],["分位数","Quantile","例如P50是中位数，P10与P90描述预测分布的相应位置。"],["区间覆盖率","Prediction interval coverage","后续真实申报值落入所给区间的比例，不是实际按期完工率。"]],"primarySource":{"title":"BSEE eWell APM：带预计天数的真实修井计划","url":"https://www.data.bsee.gov/Well/eWellAPM/Default.aspx","license":"使用公开联邦事实字段；保留BSEE来源与快照日期。第三方作业叙述不自动取得开放许可。"},"research":{"title":"BSEE A-24井公开许可：Estimated duration of the operation (days)","url":"https://www.bsee.gov/sites/bsee.gov/files/2024-08/APM%20with%20API%20043122004400%20february%202024.pdf","summary":"公开许可把ESP与油管更换的工期写为预计5天，提供了“预计工期”字段含义的直接实例，帮助在建模前确认目标口径。","boundary":"该许可没有实际完成耗时，也不是对时序或分位数模型的性能验证；课堂误差必须由保留的未来申报记录重新计算。"},"columnMap":{"file":"bsee-workover-plan-sequences.json","recordPath":"records[]","input":{"priorEstimatedDays":"同井严格更早申报的预计天数序列；只从过去构造滞后特征","priorSubmittedAt":"对应历史的原始申报时间","historyCount":"该时点已有历史数量"},"target":{"estimatedDays":"当前目标申报的EST_OPERATION_DAYS，days；计划估计，不是实际耗时"},"meta":{"planId":"目标SN_APM","wellApi":"同井历史分组键，不用来记忆标签","submittedAt":"时间排序与切分依据","plannedStartDate":"用于重复审计，不当实际开工","sameWellPlannedDateSourceRows":"同井同计划开始日的源记录数量","plannedStartBeforeSubmission":"计划日早于申报日的审计标记","temporalPartition":"177 train／59 validation／59 test；至少两条历史的有效点为123／54／56"},"excludeFromFeatures":["当前estimatedDays","sourceDescriptionSnippet中可能直接出现的工期数值","未来申报记录","ACC_STATUS_DATE等预测时尚未知的状态","仅为识别井而使用的完整API字符串"],"derived":"至少两条严格更早的申报构成历史，GRU最多读取六条；模型物理输出expected[1]为中央P50天数。有效验证点前27个选模型、后27个独立CHECK点确定绝对误差半宽；56个后续TEST点只检查覆盖，不重调参数。"},"backgroundChapters":[{"id":"context","title":"真实情境","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放依据","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难点与边界","fields":["limits"]},{"id":"glossary","title":"中英术语速查","fields":["glossary10"]}],"algorithm":"历史申报序列GRU估计","color":"#3a8c8a","artImage":"assets/images/operations/workover-process-v2.webp","artBox":[1159,430,287,360]},{"id":"e1","caseId":"e1-pkn","stageId":"eor","short":"压裂参数优化","title":"同样的注入预算，怎样选择排量与时长？","question":"先训练裂缝响应代理模型，再加入压力与用液约束，推荐方案会怎样改变？","methods":["opt"],"intro":"压裂液进入岩层后，流体流动与岩石变形共同决定裂缝扩展。设计人员需要在排量、注入时间、流体黏度和施工约束之间作选择。本例从有明确假设的PKN解析模型出发，让代理模型学习裂缝响应，再搜索约束内的候选方案。","problem":"只比较排量大小会忽略时间、黏度和岩石刚度的共同作用。直接穷举许多参数组合需要重复计算；代理模型可以加快搜索，但搜索器也可能利用代理误差，把方案推向预测不可靠的边界。","why":"响应代理模型从参数—结果样本学习非线性映射，约束优化器负责搜索可行组合。两者各司其职：预测快不代表方案已经可行，最终候选仍要回到解析模型检查压力、用液和响应误差。","input":"杨氏模量E（GPa）、泊松比ν、固定缝高h（m）、总注入排量Q（m³/s）、注入时间t（s）、流体黏度μ（Pa·s），以及允许的净压力和注入体积上限。","output":"代理预测的裂缝半长（m）、入口开度（mm）和净压力（MPa）；满足约束的参数候选；候选的解析复核结果与代理误差。","data":"教学样本由本站独立实现GEOS公开验证示例中的PKN解析公式生成，并逐条标为模拟数据。输入按岩石参数情景分组，再扫描施工参数。训练集与留出集按完整岩石情景划分，同一情景的不同时间点不会混入两侧。","limits":["PKN示例采用均质岩层、固定缝高、恒黏度和可忽略滤失等假设，适用范围必须随样本一起显示。复杂天然裂缝、支撑剂输送和高度突破均未建模。","模型中的净压力描述裂缝内部压力相对闭合应力的差值，不能直接当作现场井口泵压；本例的压力上限只是教学约束。","优化目标是模拟裂缝半长，数据没有压后产量或采收率标签。半长较大不能直接解释为增油较多，也不能作为现场施工指令。"],"experiment":"固定岩石情景，逐步收紧净压力上限和用液预算，比较推荐排量与时长。把每个候选送回解析公式，检查代理判断可行的点是否真的满足约束；若没有可行点，应保留“无可行候选”，再查看是哪条约束限制了选择。","professional":[{"title":"为什么缝高会改变扩展方式","text":"PKN模型把裂缝高度约束在一定厚度内，以横向延伸描述主要扩展。它适合演示排量、时间与黏度的耦合，但在裂缝长度与高度接近或出现高度突破时，几何假设需要重新检查。"},{"title":"排量与用液量是两个约束量","text":"恒定排量时，总注入体积为Q×t。相同用液量可以由较大排量与较短时间、或较小排量与较长时间组成，压力和开度响应仍会不同，因此需要在参数组合上比较。"},{"title":"搜索结束后为什么还要复算","text":"代理模型只近似原模型的响应。优化器会不断寻找预测最有利的区域，恰好也可能进入样本稀疏处。对最终候选做解析复核，可以把代理误差与约束违例显式列出来。"}],"steps":[{"blockId":"01","name":"定义几何目标与约束","do":"把目标限定为PKN条件下的模拟半长，明确净压力、总用液量与参数上下限，并列出模型假设。","output":"带单位的目标函数、约束与适用范围。"},{"blockId":"02","name":"生成并划分模拟样本","do":"从解析公式生成参数—响应对，检查单位与几何适用条件；按完整岩石情景分组留出，保留模拟来源和生成参数。","output":"可复现的模拟样本及情景分组。"},{"blockId":"03traditional","name":"传统：解析扫描候选","do":"在相同参数边界内逐点计算PKN响应，筛除压力或用液超限的点，为搜索结果建立可核对的参照。","output":"解析响应面与可行候选清单。"},{"blockId":"03intelligent","name":"智能：代理预测并约束搜索","do":"只用训练情景拟合响应代理，先在留出情景检查半长、开度与压力误差，再用约束优化器搜索满足条件的候选。","output":"代理模型、留出误差与优化候选。"},{"blockId":"04","name":"复核候选与边界","do":"把优化候选带回解析公式，比较预测误差、目标值和约束余量；标出样本边界与无可行解情形。","output":"解析复核后的可行性记录。"},{"blockId":"05","name":"导出模拟设计对照","do":"保存情景、参数、约束、预测与解析响应，注明目标是裂缝几何，并记录模型版本和随机种子。","output":"注明模拟来源的参数方案对照表。"}],"glossary10":[["水力压裂","Hydraulic fracturing","通过注入流体使岩石裂缝张开并扩展的过程。"],["PKN模型","Perkins–Kern–Nordgren model","以固定高度和横向延伸描述裂缝的简化模型。"],["裂缝半长","Fracture half-length","从注入位置向一侧量取的裂缝延伸长度。"],["入口开度","Inlet aperture","模型中注入位置附近两侧缝面的张开距离。"],["净压力","Net pressure","裂缝内压力相对闭合应力的差值，区别于井口泵压。"],["平面应变模量","Plane-strain modulus","由E与ν换算的有效弹性模量Ep=E/(1−ν²)。"],["注入排量","Injection rate","单位时间注入的流体体积，本例使用m³/s。"],["滤失","Leak-off","压裂液从裂缝进入周围岩石的过程，本例忽略。"],["响应代理","Response surrogate","从参数—响应样本学习的快速近似模型。"],["可行域","Feasible region","同时满足参数边界、压力和用液约束的组合。"]],"primarySource":{"title":"GEOS · Viscosity-Storage-Dominated PKN Hydraulic Fracture","url":"https://geosx-geosx.readthedocs-hosted.com/en/develop/docs/sphinx/advancedExamples/validationStudies/hydraulicFracture/pknFracViscosityDominated/Example.html","license":"公开技术文档，未见独立数据许可；本例自行实现公开解析公式并生成教学模拟数据，不复制GEOS源码或声称使用实测数据。"},"research":{"title":"PKN解析响应与数值验证","url":"https://geosx-geosx.readthedocs-hosted.com/en/develop/docs/sphinx/advancedExamples/validationStudies/hydraulicFracture/pknFracViscosityDominated/Example.html","summary":"GEOS以固定缝高、黏性与储存主导的压裂问题，对照公开解析式检查数值半长、入口开度和净压力。示例明确采用SI单位，并区分总排量与四分之一对称模型的源项。","boundary":"本课从解析式建立教学参数扫描，再训练代理与优化器；这些样本没有覆盖完整施工过程，也没有产量标签，不能沿用现场增产含义。"},"columnMap":{"file":"运行时生成的PKN教学参数—响应表","recordPath":"每条记录对应一个岩石情景和施工组合","input":{"E_gpa":"杨氏模量GPa；计算前乘10^9转Pa","nu":"泊松比，无量纲","height_m":"固定缝高m","rate_m3_s":"总注入排量m³/s","duration_s":"注入时间s","viscosity_pa_s":"恒定流体黏度Pa·s"},"target":{"half_length_m":"PKN解析半长m","inlet_aperture_mm":"PKN入口开度mm","net_pressure_mpa":"PKN净压力MPa"},"meta":{"scenario_id":"由完整岩石参数定义的分组","source_kind":"simulation","split":"按情景划分的train/validation/test","constraints":"本次搜索使用的压力、体积与参数边界"},"excludeFromFeatures":["解析目标列","优化结果","scenario_id","split","source_kind"],"derived":"体积V=Q×t；可行性由独立的解析复核给出，不把优化器自身得分当真值。"},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"PKN响应代理＋压力体积约束","color":"#b95739","artImage":"assets/images/operations/eor-process-v2.webp","artBox":[4,430,294,345]},{"id":"e2","caseId":"e2-fracture","stageId":"eor","short":"裂缝形态推断","title":"一团微地震事件，能说明怎样的空间包络？","question":"CNN能否从模拟事件密度图恢复椭圆参数，几何优化又会怎样修正初始包络？","methods":["cv","opt"],"intro":"压裂监测记录的是岩石发生微小破裂时的事件位置，事件云为改造范围提供间接线索。裂缝本体通常没有可直接拍摄的完整真值。本例先用有明确椭圆标签的模拟密度图训练CNN，再把真实FORGE事件云用于域外的定性检查。","problem":"事件稀疏、定位误差和少量离群点会改变图上看到的范围，二维投影还会压缩三维结构。把事件最外缘直接画成裂缝边界，容易给出过度确定的解释。","why":"CNN学习密度图中的方向与尺度，输出椭圆几何的初值；稳健几何优化再根据事件分布调整参数。模拟图有可检查的标签，真实事件云提供另一种分布，能直接观察学习方法跨域后出现的偏差。","input":"模拟事件密度图及其椭圆中心、长短轴和方向标签；真实目录的时间、经纬度、深度与定位标准差，经局部米制坐标转换后形成投影密度图。","output":"模拟留出图上的椭圆参数误差与包络重合度；CNN初值和优化后包络的对照；真实FORGE事件云上的定性包络及定位不确定性提示。","data":"训练图由本站独立生成，改变椭圆几何、事件密度、定位噪声和离群比例，并逐条标明synthetic。真实资料来自CC BY 4.0的Utah FORGE 2024年刺激事件目录，共2,948个已定位事件。FORGE属于增强地热项目，目录没有裂缝边界、开度、导流能力或增油真值。","limits":["椭圆只是低维事件包络，不能表达完整裂缝网络。落在包络内的区域不代表都已张开、被支撑或具备导流能力。","模拟数据的椭圆标签是生成时给定的参数，不能充当真实FORGE裂缝标签。真实图上的模型结果只做定性展示，不计算“真实裂缝识别率”。","地热事件云与油气压裂的岩性、监测系统和施工条件不同。投影、筛选阈值及定位误差都会改变包络，跨域结果需要独立证据复核。"],"experiment":"固定同一批事件，提高加权覆盖目标或改变稳健修剪比例，比较CNN初值与迭代包络的轴长、方向和全部事件落入率。再在受控模拟与真实FORGE记录间切换：有生成器参考时能检验什么，没有真实裂缝标签时又只能描述什么？","professional":[{"title":"事件位置如何产生","text":"微地震目录先从传感器波形识别到时，再关联事件并定位。FORGE开放目录使用自动拾取、事件关联与位置求解流程，并通过重复抽样给出位置标准差；这些位置本身也是处理结果。"},{"title":"微地震云为何不等于裂缝表面","text":"能被检测到的事件与监测覆盖、背景噪声和破裂机制有关。裂缝可能存在没有可检测事件的部分，事件也可能来自已有裂隙的滑动，因此事件云反映的是可观测破裂活动的分布。"},{"title":"包络的大小取决于解释选择","text":"投影方向、密度归一化和对离群点的处理都会影响包络。本例让CNN提供几何初值，再以稳健损失优化，以便把图形判断与参数调整过程放在一起检查。"}],"steps":[{"blockId":"01","name":"限定事件包络任务","do":"定义椭圆参数、投影方向和密度图范围；区分模拟椭圆标签、真实事件位置和不可直接观测的裂缝几何。","output":"可检验的模拟任务与真实资料解释范围。"},{"blockId":"02","name":"准备两种来源的图","do":"生成带参数标签的模拟密度图，按底层几何情景分组；真实事件另做局部米制转换、定位质量检查与统一投影。","output":"模拟训练/留出图和独立的真实域外图。"},{"blockId":"03traditional","name":"传统：协方差几何拟合","do":"根据相同事件的中心、主方向和离散程度建立椭圆基线，记录离群点和阈值怎样改变轴长。","output":"可解释的几何基线与参数。"},{"blockId":"03intelligent","name":"智能：CNN初值加稳健优化","do":"用模拟训练图拟合小型CNN，预测中心、轴长和周期化方向；以此为初值进行稳健几何优化，所有超参数只在模拟训练与验证情景选择。","output":"CNN初值、优化参数与模拟留出成绩。"},{"blockId":"04","name":"检查噪声与域外表现","do":"在模拟图检查参数误差和包络重合度，再定性比较真实FORGE图上的基线、CNN与优化结果，保留定位不确定性。","output":"模拟误差对照和真实域外检查记录。"},{"blockId":"05","name":"导出包络解释","do":"保存事件筛选、坐标转换、投影、模型版本和包络参数；导出时标注事件包络及synthetic/observed来源。","output":"带来源与解释条件的空间包络图。"}],"glossary10":[["微地震事件","Microseismic event","监测系统能够检测并定位的一次小规模破裂活动。"],["震源位置","Hypocenter","由波形与速度等信息估计的事件发生位置。"],["事件云","Event cloud","许多已定位事件在空间中的点集。"],["定位标准差","Location standard deviation","目录通过重复抽样等方法给出的位置不确定性量。"],["密度图","Density image","将投影区域内事件数量或平滑密度表示成像素。"],["空间包络","Spatial envelope","用于概括事件分布范围的几何外形。"],["长短轴","Major and minor axes","椭圆沿主方向及其垂直方向的尺度。"],["稳健损失","Robust loss","减小少量极端残差对几何拟合影响的目标函数。"],["重合度","Intersection over union","两个区域交集面积与并集面积之比，本例只对模拟标签评价。"],["域外检查","Out-of-domain inspection","将模拟训练方法用于不同分布资料后做独立检查。"]],"primarySource":{"title":"Utah FORGE · 2024刺激阶段微地震事件目录","url":"https://gdr.openei.org/submissions/1817","license":"真实目录CC BY 4.0；CNN训练图由本站独立生成并标为synthetic，二者分别标明来源。"},"research":{"title":"Microseismic Location in EGS: Comparing picking-based and source-imaging workflows on downhole DAS data","url":"https://gdr.openei.org/submissions/1817","summary":"开放记录配套论文比较井下DAS资料的事件定位流程；目录结合自动拾取、关联与位置求解，并用200次重复抽样估计空间标准差，为检查事件位置及不确定性提供依据。","boundary":"论文与目录没有提供用于本课椭圆回归的真实裂缝标签。本课CNN在独立模拟图上训练，稳健包络优化也不等同于该定位工作。"},"columnMap":{"file":"forge_microseismic.csv；另有运行时生成的模拟密度图与标签","recordPath":"真实CSV每行一个事件；模拟每条记录一张图及底层geometry_id","input":{"synthetic_image":"归一化事件密度栅格，不绘入参数或标签","longitude/latitude":"经纬度，度；先转换到局部米制坐标","depth_km":"目录深度km，保留源坐标参考，不直接当作地下井深","sigma_x_km/sigma_y_km/sigma_z_km":"位置标准差km；展示时换算m"},"target":{"ellipse_parameters":"仅模拟图具有中心、轴长与方向标签；方向可编码为sin(2θ)、cos(2θ)","real_FORGE":"无真实裂缝参数或分割标签"},"meta":{"time":"事件原始时间，用于日期分组","event_index":"事件ID","geometry_id":"同一模拟几何及其增广图共同分组","source_kind":"synthetic或observed-geothermal"},"excludeFromFeatures":["模拟椭圆标签","geometry_id","事件ID","split","真实资料的伪造裂缝标签"],"derived":"真实米制范围单独保留；只在模拟留出集评价轴长、方向与IoU，不用真实包络自身作为真值。"},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"事件密度CNN＋稳健椭圆包络","color":"#497d99","artImage":"assets/images/operations/eor-process-v2.webp","artBox":[306,430,272,345]},{"id":"e3","caseId":"e3-polymer","stageId":"eor","short":"化学驱浓度筛选","title":"达到目标流动阻力，最低需要多高的聚合物浓度？","question":"只有15条岩心实验记录，高斯过程能否给出有依据的浓度候选与不确定性？","methods":["opt"],"intro":"聚合物驱通过改变注入液的流动特性改善驱替过程，浓度选择需要同时考虑流动阻力与注入条件。室内岩心实验能够测量一定条件下的阻力系数。本例把问题收窄到一种表面活性聚合物的浓度筛选。","problem":"浓度越高并不意味着现场方案越好，岩心渗透率也会改变流动响应。现有实验只覆盖少数浓度和岩心条件，直接把光滑曲线上的任何点都当作已验证配方，会高估资料能回答的问题。","why":"高斯过程将浓度与渗透率映射到阻力系数RF，同时给出随样本位置变化的模型不确定性。约束搜索只在已覆盖的参数范围内寻找满足RF要求的较低浓度，再把候选交给补充实验。","input":"聚合物浓度c（mg/L）、岩心渗透率k（10⁻³ μm²），以及希望达到的阻力系数下限；模型输入仅使用c与k。","output":"预测阻力系数及模型不确定性；边界内满足条件的最低浓度候选，或无可行候选提示；按浓度组留出的预测误差。","data":"开放实验工作簿中有5个浓度水平750、1000、1250、1500、2000 mg/L，与3个岩心渗透率水平100、200、500（10⁻³ μm²）组成15条阻力系数记录，许可为CC BY 4.0。另有5条黏度—采收率记录，属于另一张实验表，未进入本例输入与目标，不能拼成这15条记录的采收率标签。","limits":["15条记录仅覆盖一种材料及有限实验条件，不能训练多组分配方模型，也没有表面活性剂比例、矿化度和温度的系统扫描。","RF是阻力系数，反映给定实验条件下的流动响应；提高RF并不自动等于提高采收率或现场增油，过大阻力也可能妨碍注入。","高斯过程区间受核函数、噪声假设和样本覆盖影响，不能直接当作经过现场校准的安全概率。边界外不推荐，边界内未试验浓度仍需验证。"],"experiment":"切换整浓度组已被留出的实验记录，核对该折预测与实测。再提高阻力系数下限、收紧上限或增大标准差裕度，观察候选浓度是否改变或变成无解。候选曲线另用全部15条拟合，未测浓度仍需新实验。","professional":[{"title":"阻力系数在测什么","text":"在给定岩心和流量条件下，注聚过程与注水过程的压差比可用于描述聚合物引起的流动阻力。黏度、孔隙中的流动和材料与岩石的相互作用都可能影响它。"},{"title":"渗透率决定实验条件","text":"同样浓度进入不同渗透率岩心时，响应可能不同。源表把渗透率写为10⁻³ μm²，本例保留这一单位，避免把数值不加说明地换称为mD。"},{"title":"低浓度候选如何产生","text":"先给定RF要求与渗透率，再从资料覆盖范围内搜索浓度；如果使用模型下界作为条件，需要同时展示所选保守程度。候选可以帮助安排下一次实验，不应替代注入能力与驱油效果的验证。"}],"steps":[{"blockId":"01","name":"定义RF约束筛选","do":"将目标定为达到给定RF要求时降低聚合物浓度，明确渗透率条件与750—2000 mg/L的实验范围。","output":"可测目标、浓度边界与候选定义。"},{"blockId":"02","name":"还原15条实测记录","do":"只读取有明确表头的浓度、渗透率与阻力系数，按工作簿合并单元格还原浓度；将另表的采收率记录保持独立。","output":"15条带单位实测数据及5个浓度组。"},{"blockId":"03traditional","name":"传统：实验点与插值参照","do":"在相同渗透率下比较已测浓度的RF，以已测点或分段插值作为可解释参照，标明未直接测量的区间。","output":"实测响应表和插值候选。"},{"blockId":"03intelligent","name":"智能：高斯过程加约束搜索","do":"仅用每折训练浓度拟合RF(c,k)，留出完整浓度组检查误差；最终筛选时限定参数范围，并显示均值、模型区间和RF约束。","output":"留出预测、模型区间与最低浓度候选。"},{"blockId":"04","name":"检查小样本与不确定性","do":"逐组查看预测误差，比较均值与保守下界形成的可行域；遇到无可行点时保留结果，不向实验边界外延伸。","output":"候选稳定性、无解条件与补实验位置。"},{"blockId":"05","name":"导出下一轮实验候选","do":"保存候选浓度、岩心条件、RF要求和不确定性，并附原15条数据、分组及材料来源。","output":"可追溯的聚合物浓度实验建议表。"}],"glossary10":[["聚合物驱","Polymer flooding","通过注入聚合物溶液改变流动特性的驱替方法。"],["表面活性聚合物","Surface-active polymer","本数据研究的聚合物材料，不能泛化为所有配方。"],["岩心驱替","Core flooding","让流体通过岩心并记录响应的室内实验。"],["渗透率","Permeability","岩石允许流体通过的能力，本例保留源表单位。"],["阻力系数","Resistance factor","给定条件下注聚与注水压差之比等流动阻力量，本例记为RF。"],["流度控制","Mobility control","调节流体流动能力差异的过程，RF只是相关实验指标。"],["高斯过程","Gaussian process","用核函数描述响应相关性并预测均值与模型不确定性的方法。"],["模型下界","Model lower bound","由预测均值与不确定性构造的保守筛选参照。"],["留浓度组验证","Concentration-group holdout","把一个浓度的三个岩心记录一起留出。"],["浓度候选","Concentration candidate","模型筛出的待实验浓度，不等于已验证的现场配方。"]],"primarySource":{"title":"Yu · Surface-active Polymer Flooding实验工作簿","url":"https://data.mendeley.com/datasets/ns7xbjz54h/1","license":"CC BY 4.0；保留原工作簿表头、单位、作者及DOI 10.17632/ns7xbjz54h.1。"},"research":{"title":"Performance of enlarging swept volume by Surface-active Polymer flooding for enhancing oil recovery","url":"https://doi.org/10.1080/15567036.2019.1656306","summary":"研究通过室内实验考察表面活性聚合物的流度控制、乳化堵调与扩大波及范围，开放工作簿包含可独立辨认的阻力系数表和黏度—采收率表。","boundary":"本课高斯过程使用阻力系数表的15条记录，未复现原研究全部实验，也未建立浓度到采收率或现场增油的映射。"},"columnMap":{"file":"polymer_resistance_factor.csv；polymer_recovery.csv仅独立参照","recordPath":"每行一条有单位的岩心实验记录","input":{"polymer_concentration_mg_l":"聚合物浓度mg/L，5个水平","permeability_1e_minus_3_um2":"岩心渗透率10⁻³ μm²，100/200/500"},"target":{"resistance_factor":"实测阻力系数RF，无量纲"},"meta":{"experiment_id":"源表编号","concentration_group":"按浓度整体留出的分组；同组有3个渗透率记录","source_kind":"laboratory-measured"},"excludeFromFeatures":["resistance_factor","同浓度平均RF","experiment_id","concentration_group","另一张表的采收率"],"derived":"合并单元格的浓度只在对应源表行内还原；平均值不是额外实验，另表的5条采收率不能与15条RF记录逐行拼接。"},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"高斯过程回归＋浓度约束筛选","color":"#8b65a0","artImage":"assets/images/operations/eor-process-v2.webp","artBox":[589,430,271,345]},{"id":"e4","caseId":"e4-steam","stageId":"eor","short":"蒸汽注入情景优化","title":"给定未来注汽计划，三个月产油预测会怎样变化？","question":"GRU如何读取真实CSS月度历史，又如何在注汽预算内比较三个月条件情景？","methods":["ts","opt"],"intro":"蒸汽吞吐通过注汽、浸泡与生产使稠油受热后流动，温度与生产状态具有时间延续性。开放资料提供了三个CSS运营项目的月度注汽与产油汇总。本例从这些真实历史建立条件预测，再比较有边界的三个月注汽情景。","problem":"注汽多的月份可能也有更多投产井或不同生产阶段，月度关联包含许多未记录因素。单看同期注汽与产油散点不能识别干预效果；同时，数据按项目汇总，不能还原一口井的注汽、焖井与开井周期。","why":"GRU把连续历史压缩成状态，并结合指定月份的注汽输入给出产油条件预测。优化器在训练资料覆盖范围、月间调整幅度和总注汽预算内比较三个月情景；它搜索的是模型预测，结果仍受观察数据关联限制。","input":"CSS项目连续月度的产油量Oil（m³/月）与注汽量SteamINJ（15°C冷水当量m³/月），过去的时间顺序，以及明确给定的未来三个月注汽情景和预算。","output":"留出月份的GRU预测、持平基线及误差；各注汽情景下三个月预测产油量与累计值；预算、月间调整和历史范围的可行性检查。","data":"原开放工作簿含2015—2019年20个运营单位的1,127条月记录，许可为CC BY 4.0。本例仅取Method=CSS的180条：UID 1 Cold Lake（IMOCL）、UID 3 CNRL Wolf Lake, Primrose, and Burnt Lake（CNRLWL）、UID 17 PeaceRiver（CNULPR），各60个月。使用Operation或UID分组，避免同名Scheme混合。","limits":["数据只有三个CSS项目、五年月度记录，深度模型样本有限。需要同时报告持平或简单回归基线；GRU在某次划分上更好不能证明其普遍优势。","注汽计划下的预测表达观察数据中的条件关联，不是注汽的因果增油量。模型未控制井数、投产进度、温度、蒸汽干度、浸泡时间等因素，优化候选需要工程复核。","月记录不是单井吞吐周期。同期SOR=SteamINJ/Oil直接含产油目标，不能拿它预测同期Oil；三个月预测也不能偷读未来实测产油。","历史测试若给入实测未来注汽，评价的是已知注汽条件下的产油响应预测；这与提前预测未知注汽计划不同，必须在结果旁说明给定条件。"],"experiment":"先固定同一段留出历史，比较GRU与产油持平基线；再给定三个月总注汽预算，允许在限定幅度内调整每月注汽。观察模型如何分配预算，并逐项查看候选是否越过历史范围。把累计预测差写为情景差值，继续检查模型误差是否大于这个差值。","professional":[{"title":"蒸汽量为什么用冷水当量","text":"源资料把注汽体积折算为15°C的冷水体积，使不同月份可以按统一体积口径比较。它没有同时给出蒸汽干度与焓，因此相同冷水当量不保证注入相同热量。"},{"title":"项目月量与单井周期的差别","text":"一个CSS运营项目可能有多口井处于不同阶段，月汇总把这些过程加在一起。月度产油变化可用于运营条件预测，但不能据此识别某口井的浸泡时长或优化开井时机。"},{"title":"三个月预测怎样保持时间顺序","text":"每一步读取已有历史和该步给定注汽，输出下个月的产油预测；继续预测时只能使用此前的模型输出。训练、验证和测试按时间分开，并单独检查留出项目后的适用性。"}],"steps":[{"blockId":"01","name":"定义三个月条件情景","do":"明确目标是给定注汽计划的月度产油预测，规定三个月总预算、每月边界与调整幅度，并说明关联解释范围。","output":"带单位的预测任务与情景约束。"},{"blockId":"02","name":"按CSS项目整理时间线","do":"只取UID 1、3、17，按项目与月份排序；核对连续性与冷水当量单位。UID 1、3按2015—2017训练、2018验证、2019测试；UID 17完整留作跨项目检验，所有缩放仅用训练期。","output":"180条真实CSS月量和无跨项目混接的序列。"},{"blockId":"03traditional","name":"传统：产油持平与简单关联","do":"在相同预测起点给出上月产油持平基线，或只用训练期拟合简洁关联模型；用相同测试月份评价误差。","output":"有共同评价口径的基线预测。"},{"blockId":"03intelligent","name":"智能：GRU预测并搜索计划","do":"仅用训练期拟合缩放与GRU，结合给定未来注汽递推三个月产油；在历史覆盖、预算和月间调整约束内搜索计划，不使用未来实测Oil。","output":"GRU条件预测与有边界的三个月候选。"},{"blockId":"04","name":"比较误差与情景差值","do":"同时展示留出误差、逐月预测和预算使用，检查最优候选是否停在样本边界，并比较项目留出时误差是否增加。","output":"情景可行性、模型稳定性与误差记录。"},{"blockId":"05","name":"保存计划假设","do":"导出项目、预测起点、已有历史、给定注汽、预测产油和约束；注明条件关联、模型版本与尚未纳入的现场因素。","output":"可复核的月度条件情景对照表。"}],"glossary10":[["蒸汽吞吐","Cyclic steam stimulation","通过注汽、浸泡与生产等阶段使稠油受热采出的方式，简称CSS。"],["冷水当量","Cold-water equivalent","把蒸汽量折算为规定温度下的液态水体积。"],["项目月量","Scheme-month volume","一个运营项目在一个月内汇总的体积。"],["注汽产油体积比","Steam-to-oil ratio","注汽冷水当量体积与产油体积之比，简称SOR；此处“汽”指蒸汽。"],["门控循环单元","Gated recurrent unit","通过门控保存和更新历史状态的时序网络，简称GRU。"],["条件预测","Conditional forecast","在明确给定未来注汽等条件下得到的预测。"],["持平基线","Persistence baseline","把最近一次观测值作为下一步预测的简单参照。"],["递推预测","Recursive forecast","多步预测中用先前模型输出继续推进时间。"],["注汽预算","Steam budget","情景内允许注入的冷水当量总体积。"],["因果效应","Causal effect","改变干预造成的响应变化，本月量关联模型不能直接识别。"]],"primarySource":{"title":"Si · Canadian In Situ Oil Sands月度运营数据","url":"https://data.mendeley.com/datasets/8ngkgz69zb/2","license":"CC BY 4.0；数据来自作者整理的Petrinex公开运营记录，逐条保留UID、Operation、月份与方法。"},"research":{"title":"Discovering Energy Consumption Patterns with Unsupervised Machine Learning for Canadian In Situ Oil Sands Operations","url":"https://doi.org/10.3390/su13041968","summary":"原研究从运营资料整理注汽、产油和气体等月量，用聚类与关联规则观察能耗模式。论文表2明确给出油与蒸汽的体积单位，并说明蒸汽以15°C冷水当量报告。","boundary":"本课从同一开放数据中选择三个CSS项目另建GRU条件预测与三个月约束情景，不复用原论文成绩，也不把原文的关联发现解释为因果控制规律。"},"columnMap":{"file":"oil_sands_monthly.csv","recordPath":"每行一个Operation在一个月的汇总；只取Method=CSS","input":{"past Oil":"过去月份产油m³/月","past SteamINJ":"过去注汽m³冷水当量/月，15°C","given future SteamINJ":"显式给定的未来三个月计划；实际历史评价与情景假设分开"},"target":{"future Oil":"对应未来月份的实测产油m³/月，仅用于监督与评价"},"meta":{"UID":"CSS取1、3、17","Operation":"IMOCL / CNRLWL / CNULPR","Scheme":"Cold Lake / CNRL Wolf Lake, Primrose, and Burnt Lake / PeaceRiver","ProductionMonth":"YYYY-MM，排序与划分依据","Method":"CSS；其他记录是SAGD","gas units":"SGF、Flare、Vent、SolutionGas按源文为10³ m³/月，不能与油的m³混用"},"excludeFromFeatures":["同期SOR","任何未来实测Oil","未来GHG或EI等含同期产量的派生指标","全数据拟合的缩放参数","跨项目滚动窗口"],"derived":"同期SOR=SteamINJ/Oil；默认模型仅用油与注汽。三个月累计量按月量求和，情景差值不是因果增油。"},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"条件GRU＋有限蒸汽方案搜索","color":"#6b884b","artImage":"assets/images/operations/eor-process-v2.webp","artBox":[867,430,286,345]},{"id":"e5","caseId":"e5-microbial","stageId":"eor","short":"微生物产物软测量","title":"化验结果返回前，传感器能估计多少表面活性产物？","question":"只读检测前的在线记录，时序模型能否估计发酵液中的海藻糖脂浓度？","methods":["ts"],"intro":"微生物产生的表面活性物质是微生物提高采收率研究中的一种途径，产物形成需要通过实验测量。本例选用Rhodococcus sp. PML026的真实罐外发酵记录，学习怎样在离线化验尚未返回时，用在线过程信号估计产物浓度。","problem":"在线转速、温度和溶氧记录密集，产物化验却每24小时才有一次。把化验值向前后铺满传感器行，会凭空增加标签数量；让模型读取检测之后的信号，则会把未来信息带进当前估计。","why":"只读过去信息的时序模型从24小时传感器变化提取过程状态，输出同一时刻待化验的产物浓度。它承担软测量任务，训练与评价始终只对真实离线检测值计算，并把重复批次保留在同一条件组。","input":"检测时刻t之前24小时的转速（rpm）、温度（°C）和溶氧（%饱和度），按实际时间分别对齐并汇总为24个小时段；不输入当前产物、菌体或其他离线化验。","output":"时刻t的海藻糖脂浓度估计（g/L）、实际检测值与误差；按发酵条件留出的评价；每个输入窗口的观测数量与时间范围。","data":"Mendeley公开CSV包含B1、B2a、B2b、B3四次PML026发酵，每批0—360小时有16次离线产物检测，共64个真实标签。当前对齐文件保留60个标签：每批起始0小时没有过去24小时记录，因此各排除1个。三个通用在线信号逐小时取均值，每个小时段至少有52条实际观测，未插值或填入未来值。许可为CC BY 4.0。","limits":["四批实验只有三个条件组，B2a与B2b是重复发酵，不能一批训练、一批测试后宣称跨条件泛化。大量分钟传感器记录不会把60个化验标签变成数万次独立实验。","输出是罐外发酵液的海藻糖脂浓度，不是油藏菌群活性、驱油效率或现场增油量。实验没有矿场产量标签，不能据此建议现场营养液注入。","“只读过去”说明模型的信息时间边界，不代表识别了转速、温度或溶氧的因果效应。B2b的pH使用稀疏独立时钟，当前通用三信号数据不纳入pH，也不补齐它。"],"experiment":"切换B2a与B2b的留出化验记录，核对24小时窗口严格早于检测时间。固定一条记录后给DO加入受控偏置，观察输出变化；原化验值只作原状态参照，不能当新情景真值，也不能把模型敏感性说成因果机制。","professional":[{"title":"产物、菌体与活性不是同一个量","text":"菌体干重、光密度和表面活性产物浓度描述不同方面。某时刻菌体较多不保证产物同步较高。本例将海藻糖脂g/L作为唯一目标，其他离线检测值不进入输入，避免用化验结果替代在线信号。"},{"title":"不同信号必须各按时间对齐","text":"原CSV把多种信号并排存放，一行的不同列不一定属于同一时刻。转速、温度和溶氧各读取自己的时间列，再只汇总[t−24,t)内的记录，不能按表格行号直接拼接。"},{"title":"软测量如何接受独立检验","text":"模型在时刻t仅使用已出现的在线记录，待真实化验返回后才计算误差。验证时把相同条件的重复发酵一起留出，并让缩放与参数拟合只读取训练条件，使评价反映新条件下的适用性。"}],"steps":[{"blockId":"01","name":"定义在线软测量时刻","do":"将目标定为时刻t的实测海藻糖脂浓度，输入只允许使用t之前24小时的在线转速、温度和溶氧。","output":"带时间边界与g/L单位的目标定义。"},{"blockId":"02","name":"对齐传感器与60个标签","do":"从各自时间列读取三种信号，按小时汇总实际观测；起始检测因无历史而排除。保留B1、B2、B3条件分组，B2a与B2b共同属于B2。","output":"60个真实标签及每条24×3的历史窗口。"},{"blockId":"03traditional","name":"传统：训练条件参考值","do":"仅用训练条件的真实化验建立均值或简单过程关联基线，在相同留出条件上预测，不使用留出化验均值。","output":"有相同时间边界的基线估计。"},{"blockId":"03intelligent","name":"智能：过去窗口时序估计","do":"只用B1、B3在24—288小时的24个标签训练小型时序模型，其312、336、360小时共6个标签用于时间验证；B2a与B2b的30个标签共同留出。缩放只用24个训练窗口拟合，损失不对分钟传感器伪造标签。","output":"留出条件的产物浓度估计与模型记录。"},{"blockId":"04","name":"检查误差与时间泄漏","do":"逐条对照估计、真实化验与前24小时曲线，检查最后输入时间早于标签时间；分别报告B2a、B2b两个重复批次及B2整体的留出误差，并与训练期均值基线对照。","output":"条件分组误差与可核查的时间窗口。"},{"blockId":"05","name":"保存软测量结果","do":"导出批次、条件、检测时间、输入区间、估计与实测值，附原始数据哈希、观测计数和排除记录。","output":"可追溯的实验室软测量对照表。"}],"glossary10":[["微生物提高采收率","Microbial enhanced oil recovery","研究微生物或其产物参与提高采收率的方法，简称MEOR。"],["罐外发酵","Ex-situ fermentation","在受控发酵装置中培养微生物并生产产物。"],["海藻糖脂","Trehalolipid","本实验测量的一类生物表面活性产物，浓度单位g/L。"],["在线信号","Online signal","过程运行时持续记录的传感器数据。"],["离线化验","Offline assay","取样后分析得到的检测值，本例每24小时一次。"],["溶氧","Dissolved oxygen","培养液中的氧水平，本数据以饱和度百分比报告。"],["软测量","Soft sensing","用易获得的过程信号估计需要化验的变量。"],["历史窗口","History window","预测时刻之前的一段输入序列，本例为24小时。"],["条件组留出","Condition-group holdout","将相同发酵条件及其重复批次整体留出评价。"],["未来信息泄漏","Future information leakage","输入或预处理中使用预测时点之后才获得的信息。"]],"primarySource":{"title":"PML026 · Production and separation of a trehalolipid biosurfactant: data","url":"https://data.mendeley.com/datasets/bw79v9vnbs/1","license":"CC BY 4.0；原始data.csv保留为biosurfactant.csv，64个原始标签及60个对齐样本分别记录。"},"research":{"title":"Production and separation of a trehalolipid biosurfactant","url":"https://doi.org/10.1016/j.bej.2018.07.006","summary":"研究用Rhodococcus sp. PML026在摇瓶和生物反应器中生产海藻糖脂，并研究底物耗尽、产物形成与泡沫分离。开放资料提供过程传感器、菌体及产物检测，支持检查发酵随时间的变化。","boundary":"本课的在线窗口时序模型另行建立，使用真实产物化验监督；实验室产物浓度不等同于油藏菌群活性或现场采收率，不能移用为增油验证。"},"columnMap":{"file":"biosurfactant_online_windows.json","recordPath":"samples[]；60条记录，每条一个实测离线标签","input":{"x[:,0]":"24个小时段的转速均值rpm","x[:,1]":"24个小时段的温度均值°C","x[:,2]":"24个小时段的溶氧均值%饱和度","window":"从旧到新排列；第i段为[assay_time_h−24+i,assay_time_h−23+i)"},"target":{"target_trehalolipid_g_l":"时刻assay_time_h的真实海藻糖脂化验g/L"},"meta":{"batch_id":"B1/B2a/B2b/B3，保留批次","condition_group":"B1/B2/B3；B2a和B2b同组","assay_time_h":"真实检测时间h，用于对齐与检查","sensor_count_per_bin":"每个小时段各信号的实际观测数","last_sensor_time_h":"各输入信号最后观测时间，必须早于assay_time_h","target_assay_std_g_l":"源表化验标准差，仅供展示"},"excludeFromFeatures":["target_trehalolipid_g_l","target_assay_std_g_l","任何当前或历史产物化验","菌体干重","OD600","蛋白与底物化验","batch_id","condition_group","未来传感器","稀疏pH"],"derived":"三个信号各按自身时间列独立聚合；不插值、不向前或向后填充值。64个原始标签中4个起始标签无24小时历史而排除，60个输入窗口均有实际观测。"},"backgroundChapters":[{"id":"context","title":"真实背景","fields":["intro","problem","professional","why"]},{"id":"research","title":"研究与开放资料","fields":["research","primarySource"]},{"id":"data","title":"数据与实验","fields":["input","output","data","columnMap"]},{"id":"limits","title":"难度与边界","fields":["limits"]},{"id":"glossary","title":"中英术语对照","fields":["glossary10"]}],"algorithm":"过去传感器窗口GRU软测量","color":"#3a8c8a","artImage":"assets/images/operations/eor-process-v2.webp","artBox":[1159,430,287,345]}];g.OPERATIONS_STAGES={"production":{"name":"采油","en":"PRODUCTION","index":"09","headline":"把每一口井的变化，变成可核对的生产判断","lead":"先理解举升、注水与计量，再看诊断、预测和调配怎样帮助日常生产。","relation":"五项任务共享井号和时间基准，彼此互补；P1—P5是案例编号。配注示例作用于井间总液响应，不代表已完成分层配注。","flow":"生产记录 → 工况候选、预测与约束调配 → 工程复核","top":430,"height":340,"image":"assets/images/operations/production-process-v2.webp"},"workover":{"name":"修井","en":"WORKOVER","index":"10","headline":"围绕同一口井，核对方案、工具与作业风险","lead":"从井筒状态与作业目标出发，认识检索、尺寸匹配、测厚和过程监测的不同任务。","relation":"五项任务围绕同一井筒与作业记录互补，不是必须依次运行的五道工序。W1—W5是案例编号。","flow":"井史与检测资料 → 方案与工具候选 → 现场复核与记录","top":430,"height":360,"image":"assets/images/operations/workover-process-v2.webp"},"eor":{"name":"增采","en":"ENHANCED RECOVERY","index":"11","headline":"从储层与流体入手，比较增采方案的条件","lead":"理解压裂、化学驱、热采与微生物研究怎样作用，再比较模型能回答的具体问题。","relation":"压裂、化学驱、蒸汽与微生物是不同技术路径；E1—E5是案例编号，不表示依次实施。试验与模拟的范围分别保留。","flow":"储层与流体条件 → 模型与方案比较 → 约束、验证与复核","top":430,"height":345,"image":"assets/images/operations/eor-process-v2.webp"}};})(window);
